import static io.mark.hditemicons.hd.ItemIconRasterizer.ICON_HEIGHT;
import static io.mark.hditemicons.hd.ItemIconRasterizer.ICON_WIDTH;

/**
 * Replaces the game's 36x32 item icons with antialiased software renders of the item models,
 * painted directly into the frame buffer over each item widget. The item widget itself is
 * never touched, so clicks, drags and menu actions all keep working exactly as before; only
 * the pixels the game already drew for that slot are repainted.
 * <p>
 * The game doesn't expose an item's icon camera framing through the public API, so for every
 * distinct (item, quantity, border) combination we first ask the client to draw its own icon,
 * and {@link ItemIconRasterizer} numerically fits our own camera to match that silhouette
 * before trusting the render. Rendering itself happens on a background thread pool; only the
 * final compositing into the live frame buffer runs synchronously during overlay drawing.
 */
@Slf4j
@Singleton
public class HdItemIcons extends WidgetItemOverlay {
	private static final int MAX_CACHED_ICONS = 2048;
	private static final int MAX_CACHED_REFERENCES = 2048;
	private static final int MAX_CACHED_STACK_MODELS = 512;
	private static final int MAX_NEW_RENDERS_PER_FRAME = 16;
	// An animation is at most 128 cycles long, so this is how much of one is kept at worst
	private static final int MAX_ANIMATION_FRAMES = 32;
	private static final int[] KEPT_CONTAINERS = {InventoryID.INV, InventoryID.WORN};
	private static final float DRAGGED_OPACITY = 128 / 256f;
	private static final float MIN_SHAPE_COVERAGE = .9f;

	// We paint a small margin around the icon too, since our render can spill slightly past
	// the game's own tighter bounding box.
	private static final int MARGIN = 2;
	private static final int PATCH_WIDTH = ICON_WIDTH + 2 * MARGIN;
	private static final int PATCH_HEIGHT = ICON_HEIGHT + 2 * MARGIN;
	// A pass spreads one pixel, so this is the most it can take to cross the patch
	private static final int INPAINT_PASSES = PATCH_WIDTH + PATCH_HEIGHT;
	private static final int PATCH_SIZE = PATCH_WIDTH * PATCH_HEIGHT;

	private static final byte FLAG_ITEM = 0x1;
	private static final byte FLAG_SHADOW = 0x2;
	private static final byte FLAG_STACK_TEXT = 0x4;
	private static final byte FLAG_OUTLINE = 0x8;

	private static final int[] NEIGHBOR_DX = {-1, 1, 0, 0};
	private static final int[] NEIGHBOR_DY = {0, 0, -1, 1};

	private static final int[] INVENTORY_LIKE_INTERFACES = {
		InterfaceID.INVENTORY, InterfaceID.WORNITEMS, InterfaceID.EQUIPMENT_SIDE,
		InterfaceID.BANKSIDE, InterfaceID.SHARED_BANK_SIDE, InterfaceID.BANK_DEPOSITBOX,
		InterfaceID.SHOPSIDE,
	};
	// The layers holding their items, drawn before the game draws the dragged item over them
	private static final int[] INVENTORY_LIKE_ITEM_LAYERS = {
		InterfaceID.Inventory.ITEMS, InterfaceID.EquipmentSide.ITEMS, InterfaceID.Bankside.ITEMS,
		InterfaceID.SharedBankSide.ITEMS, InterfaceID.BankDepositbox.INVENTORY, InterfaceID.Shopside.ITEMS,
	};

	/**
	 * A queued or finished render. A shared {@link #PENDING} instance stands in for "still
	 * being worked on" so callers don't need a separate lookup to check.
	 */
	private static final class RenderedIcon {
		volatile boolean failed;
		volatile boolean uncached;
		volatile boolean[] outlineRing;
		volatile int[] pixels;
		// One frame per phase of the icon's animation, and how long that animation runs for in
		// client cycles. A still icon is a single frame with no period.
		volatile int[][] frames;
		volatile boolean[][] frameRings;
		volatile int period;
		int shownFrame = -1;
		int[] selectedPixels;
		boolean[] selectedOutlineRing;
		int[] selectedFrom;
		int itemId = -1;
	}

	/**
	 * A fingerprint of what the game itself drew for one (item, quantity, border) combination.
	 * Used both as the cache key for our rendered replacement and to classify every pixel of
	 * the patch around the icon as part of the item's silhouette, its drop shadow, or
	 * stack-count text, so compositing knows what it's allowed to touch.
	 */
	private static final class ReferenceIcon {
		final byte[] patchFlags = new byte[PATCH_SIZE];
		final int[] plainPixels;
		final long fingerprint;
		int resolvedModelItemId = -1;

		ReferenceIcon(int itemId, int borderWidth, int supersample, int[] plainPixels, int[] pixelsWithCount) {
			this.plainPixels = plainPixels;
			this.fingerprint = fingerprintOf(itemId, borderWidth, supersample, plainPixels);

			for (int y = 0; y < ICON_HEIGHT; y++) {
				for (int x = 0; x < ICON_WIDTH; x++) {
					int flat = y * ICON_WIDTH + x;
					int patch = patchIndex(x, y);
					if (plainPixels[flat] != 0)
						patchFlags[patch] |= FLAG_ITEM;
					if (pixelsWithCount[flat] != plainPixels[flat])
						patchFlags[patch] |= FLAG_STACK_TEXT;
				}
			}
			for (int y = 0; y < ICON_HEIGHT; y++) {
				for (int x = 0; x < ICON_WIDTH; x++) {
					int patch = patchIndex(x, y);
					boolean isItem = (patchFlags[patch] & FLAG_ITEM) != 0;
					boolean litFromUpperLeft = (patchFlags[patchIndex(x - 1, y - 1)] & FLAG_ITEM) != 0;
					if (!isItem && litFromUpperLeft)
						patchFlags[patch] |= FLAG_SHADOW;
					for (int n = 0; n < NEIGHBOR_DX.length; n++)
						if (!isItem && (patchFlags[patchIndex(x + NEIGHBOR_DX[n], y + NEIGHBOR_DY[n])] & FLAG_ITEM) != 0)
							patchFlags[patch] |= FLAG_OUTLINE;
				}
			}
		}

		boolean has(int patch, byte flag) {
			return (patchFlags[patch] & flag) != 0;
		}

		private static long fingerprintOf(int itemId, int borderWidth, int supersample, int[] pixels) {
			long h = 0xCBF29CE484222325L; // FNV-1a
			h = mix(h, itemId);
			h = mix(h, borderWidth);
			h = mix(h, supersample);
			for (int p : pixels)
				h = mix(h, p);
			return h;
		}

		private static long mix(long hash, int value) {
			for (int shift = 0; shift < 32; shift += 8)
				hash = (hash ^ (value >>> shift & 0xFF)) * 0x100000001B3L;
			return hash;
		}
	}

	private static int patchIndex(int x, int y) {
		return (y + MARGIN) * PATCH_WIDTH + (x + MARGIN);
	}

	/**
	 * Everything needed to rasterize one drawn layer of an icon (a plain item, or one half of
	 * a noted item's [paper, small item] pair).
	 */
	private static final class ModelLayer {
		final ItemIconRasterizer.IconModel model;
		final int pitchJau, yawJau, rollJau;
		final int[] referencePixels;
		final int borderWidth;
		@Nullable
		final CustomRotation placement;

		ModelLayer(ItemIconRasterizer.IconModel model, int pitchJau, int yawJau, int rollJau, int[] referencePixels, int borderWidth, @Nullable CustomRotation placement) {
			this.model = model;
			this.pitchJau = pitchJau;
			this.yawJau = yawJau;
			this.rollJau = rollJau;
			this.referencePixels = referencePixels;
			this.borderWidth = borderWidth;
			this.placement = placement;
		}
	}

	/**
	 * An item's icon put on screen this frame, and what it's composited from.
	 */
	private static final class PlacedIcon {
		final Rectangle bounds, patchArea;
		final ReferenceIcon reference;
		final int[] pixels;
		final boolean[] outlineRing;
		@Nullable
		final Slot slot;
		final int[] composed;
		int[] background;
		int[] overlays;
		int fill, outline;
		// Whether everything other overlays drew over it is drawn with it, so the dragged item can go over it all
		boolean takeAll;
		// What's drawn under the interface
		int[] drawn;
		// The game's own icon for the dragged item, wherever it was found drawn
		@Nullable
		int[] drawnByGame;

		PlacedIcon(Rectangle bounds, Rectangle patchArea, ReferenceIcon reference, int[] pixels, boolean[] outlineRing,
			@Nullable Slot slot, int[] composed) {
			this.bounds = bounds;
			this.patchArea = patchArea;
			this.reference = reference;
			this.pixels = pixels;
			this.outlineRing = outlineRing;
			this.slot = slot;
			this.composed = composed;
		}
	}

	/**
	 * What's behind an item and what other overlays draw over it rarely change, so they're only worked
	 * out again when they do.
	 */
	private static final class Slot {
		final int[] behind = new int[PATCH_SIZE];
		final int[] cut = new int[PATCH_SIZE];
		final int[] composed = new int[PATCH_SIZE];
		final int[] overlays = new int[PATCH_SIZE];
		final int[] drawn = new int[PATCH_SIZE];
		ReferenceIcon reference;
		int[] pixels;
		Rectangle patchArea;
		float opacity;
		boolean overlaid;
		boolean takeAll;
		int lastUsed;

		boolean holds(PlacedIcon placed, float opacity) {
			return reference == placed.reference && pixels == placed.pixels && placed.patchArea.equals(patchArea) && this.opacity == opacity;
		}

		void keep(PlacedIcon placed, float opacity) {
			reference = placed.reference;
			pixels = placed.pixels;
			patchArea = placed.patchArea;
			this.opacity = opacity;
			overlaid = false;
			for (int y = patchArea.y; y < patchArea.y + patchArea.height; y++) {
				for (int x = patchArea.x; x < patchArea.x + patchArea.width; x++) {
					int patch = patchIndex(x - placed.bounds.x, y - placed.bounds.y);
					cut[patch] = reference.has(patch, FLAG_STACK_TEXT) ? behind[patch] : 0;
				}
			}
		}
	}

	/**
	 * Takes what other overlays drew over the cut out items. Fills and outlines that follow the game's
	 * icon, like Inventory Tags', are redrawn to fit ours, with fills covering the shadow too. Everything
	 * else stays where it was drawn.
	 */
	private final class OverlayCapture extends WidgetItemOverlay {
		OverlayCapture() {
			for (int groupId : INVENTORY_LIKE_INTERFACES)
				drawAfterInterface(groupId);
			drawAfterLayer(InterfaceID.Bankmain.ITEMS);
			drawAfterLayer(InterfaceID.SharedBank.ITEMS);
			// After the other item overlays
			setPriority(PRIORITY_HIGHEST + 1);
		}

		@Override
		public Dimension render(Graphics2D graphics) {
			BufferProvider frame = client.getBufferProvider();
			int[] framePixels = frame.getPixels();
			int frameWidth = frame.getWidth();
			PlacedIcon draggedHere = draggedThisHook;
			draggedThisHook = null;
			for (PlacedIcon placed : cutItems) {
				// The game draws the dragged item over what it's dragged over
				placed.takeAll = draggedHere != null && draggedHere.patchArea.intersects(placed.patchArea);
				captureOverlays(framePixels, frameWidth, placed);
				placed.drawn = drawWithOverlays(placed);
				drawnUnderInterface.add(placed);
			}
			cutItems.clear();
			if (draggedHere == null)
				return null;
			if (client.isGpu()) {
				draggedHere.takeAll = true;
				captureOverlays(framePixels, frameWidth, draggedHere);
			} else {
				// What the game draws the dragged item over, once the items under it are done
				draggedHere.background = nextPatchBuffer();
				readPatch(framePixels, frameWidth, draggedHere, draggedHere.background);
			}
			return null;
		}

		@Override
		public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
		}
	}

	/**
	 * Takes the game's dragged item back out once it's drawn over the rest of the interface, and puts ours in its place.
	 */
	private final class DraggedItemPainter extends Overlay {
		DraggedItemPainter() {
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ABOVE_WIDGETS);
			setPriority(PRIORITY_LOW - 1);
		}

		@Override
		public Dimension render(Graphics2D graphics) {
			drawDraggedItem();
			return null;
		}
	}

	/**
	 * Keeps what's under the dragged item right after its layer, before the game draws it there.
	 */
	private final class DraggedItemBackdrop extends WidgetItemOverlay {
		DraggedItemBackdrop() {
			for (int layerId : INVENTORY_LIKE_ITEM_LAYERS)
				drawAfterLayer(layerId);
			// After the other overlays of the layer, which the game draws the dragged item over
			setPriority(PRIORITY_HIGHEST + 1);
		}

		@Override
		public Dimension render(Graphics2D graphics) {
			Widget draggedWidget = client.getDraggedWidget();
			if (draggedWidget == null)
				return null;
			for (WidgetItem widgetItem : overlayManager.getWidgetItems()) {
				if (widgetItem.getWidget() == draggedWidget)
					keepBackdrop(widgetItem.getCanvasBounds());
			}
			return null;
		}

		@Override
		public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
		}
	}

	/**
	 * With GPU the interface has transparency, so our icons are drawn under it once it's all drawn. Whatever is
	 * drawn over an item, like menus, other interfaces and overlays, then stays over it, wherever it came from.
	 */
	private final class UnderInterfacePainter extends Overlay {
		UnderInterfacePainter() {
			setPosition(OverlayPosition.DYNAMIC);
			setLayer(OverlayLayer.ALWAYS_ON_TOP);
			setPriority(PRIORITY_HIGHEST + 1);
		}

		@Override
		public Dimension render(Graphics2D graphics) {
			drawUnderInterface();
			return null;
		}
	}

	private static final int[] EMPTY_PATCH = new int[PATCH_SIZE];
	private static final RenderedIcon PENDING = new RenderedIcon();
	private static final ReferenceIcon UNRESOLVED =
		new ReferenceIcon(-1, 0, 0, new int[ICON_WIDTH * ICON_HEIGHT], new int[ICON_WIDTH * ICON_HEIGHT]);

	private final Client client;
	private final EventBus eventBus;
	private final OverlayManager overlayManager;
	private final ClientThread clientThread;
	private final HdItemIconsConfig config;
	private final CustomRotationStorage rotationStorage;
	private final ItemRenderSheet itemRenderSheet;
	private final OverlayCapture overlayCapture = new OverlayCapture();
	private final DraggedItemPainter draggedItemPainter = new DraggedItemPainter();
	private final DraggedItemBackdrop draggedItemBackdrop = new DraggedItemBackdrop();
	private final UnderInterfacePainter underInterfacePainter = new UnderInterfacePainter();

	private ExecutorService renderExecutor;
	private boolean active;
	private double lastKnownBrightness = Double.NaN;
	@Nullable
	private IconQuality lastKnownQuality;
	private boolean lastKnownCustomRotationsEnabled = true;
	private boolean lastKnownStretched;
	private boolean lastKnownAnimateTextures = true;
	private int animationCycle;
	@Nullable
	private Filepath iconCacheDirectory;
	@Nullable
	private ItemIconCache iconCache;
	@Nullable
	private volatile RotationEditorDialog openRotationDialog;

	private final Map<Long, RenderedIcon> renderedIcons = new LinkedHashMap<>(MAX_CACHED_ICONS, .75f, true) {
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, RenderedIcon> eldest) {
			return size() > MAX_CACHED_ICONS;
		}
	};
	private final Map<Long, ReferenceIcon> referenceIcons = new LinkedHashMap<>(MAX_CACHED_REFERENCES, .75f, true) {
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, ReferenceIcon> eldest) {
			return size() > MAX_CACHED_REFERENCES;
		}
	};
	private final Map<Long, Integer> resolvedStackModels = new LinkedHashMap<>(MAX_CACHED_STACK_MODELS, .75f, true) {
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, Integer> eldest) {
			return size() > MAX_CACHED_STACK_MODELS;
		}
	};
	// Not access-ordered: an in-progress search must keep its resume point until it either
	// finishes or is evicted for staying idle the longest, not for being actively read.
	private final Map<Long, Integer> stackModelSearchProgress = new LinkedHashMap<>(MAX_CACHED_STACK_MODELS, .75f, false) {
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, Integer> eldest) {
			return size() > MAX_CACHED_STACK_MODELS;
		}
	};
	private final Map<Integer, Item[]> watchedContainers = new HashMap<>();
	// Containers whose items all have their icons ready (or found ineligible),
	// so the prefetch pass can skip re-scanning them every frame - this matters a lot for the
	// bank, which can hold 800+ slots.
	private final Set<Integer> settledContainers = new HashSet<>();

	private int rendersStartedThisFrame;
	private int frameCount;
	private final Set<Rectangle> paintedThisFrame = new HashSet<>();
	private final Map<Rectangle, Slot> slots = new HashMap<>();
	private final List<PlacedIcon> cutItems = new ArrayList<>();
	private final List<PlacedIcon> drawnUnderInterface = new ArrayList<>();
	@Nullable
	private PlacedIcon dragged;
	@Nullable
	private PlacedIcon draggedThisHook;
	private int backdropFrame = -1;
	private final Rectangle backdropBounds = new Rectangle();
	private final int[] backdrop = new int[PATCH_SIZE];
	private final List<int[]> patchBuffers = new ArrayList<>();
	private int patchBuffersUsed;
	private final int[] patchColor = new int[PATCH_SIZE];
	private final boolean[] patchResolved = new boolean[PATCH_SIZE];
	private final boolean[] patchResolvedScratch = new boolean[PATCH_SIZE];

	private int[] cachedPalette;
	private double cachedPaletteBrightness;

	@Inject
	public HdItemIcons(Client client, EventBus eventBus, OverlayManager overlayManager, ClientThread clientThread,
						HdItemIconsConfig config, CustomRotationStorage rotationStorage, ItemRenderSheet itemRenderSheet) {
		this.client = client;
		this.eventBus = eventBus;
		this.overlayManager = overlayManager;
		this.clientThread = clientThread;
		this.config = config;
		this.rotationStorage = rotationStorage;
		this.itemRenderSheet = itemRenderSheet;
		for (int groupId : INVENTORY_LIKE_INTERFACES)
			drawAfterInterface(groupId);
		drawAfterLayer(InterfaceID.Bankmain.ITEMS);
		drawAfterLayer(InterfaceID.SharedBank.ITEMS);
		// Ahead of other item overlays, so they draw on top of our replacement icon
		setPriority(PRIORITY_LOW - 1);
	}

	/**
	 * @param dataDirectory the plugin's data directory. Only used if the disk icon cache is
	 *                      enabled in config.
	 */
	public void startUp(Filepath dataDirectory) {
		renderExecutor = Executors.newFixedThreadPool(config.renderThreadCount(), runnable -> {
			Thread thread = new Thread(runnable, "hd-item-icon-renderer");
			thread.setDaemon(true);
			return thread;
		});

		iconCacheDirectory = null;
		try {
			if (!dataDirectory.isDirectory())
				dataDirectory.createDirectories();
			rotationStorage.load(dataDirectory);
			if (config.iconCacheStorage() == IconCacheStorage.DISK) {
				iconCacheDirectory = dataDirectory;
				renderExecutor.execute(() -> ItemIconCache.removeUnused(dataDirectory));
			}
		} catch (IOException e) {
			log.debug("Couldn't create the plugin data directory {}; icon cache and custom rotations will be memory only", dataDirectory, e);
		}

		active = true;
		eventBus.register(this);
		clientThread.invoke(() -> {
			// clientThread.invoke() just queues this for the next client tick if we're not
			// already on it - it isn't tied to our lifecycle. If the plugin is toggled off
			// again before this runs, shutDown() can finish first; without this guard we'd
			// re-add the overlay after shutdown already tore everything down, leaking it
			// with no way left to remove it.
			if (!active)
				return;
			// Also when turned on after logging in, before any of them changes
			for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN, InventoryID.BANK}) {
				ItemContainer container = client.getItemContainer(containerId);
				if (container != null)
					watchedContainers.put(containerId, container.getItems());
			}
			overlayManager.add(this);
			overlayManager.add(overlayCapture);
			overlayManager.add(draggedItemPainter);
			overlayManager.add(draggedItemBackdrop);
			overlayManager.add(underInterfacePainter);
		});
	}

	public void shutDown() {
		if (!active)
			return;
		active = false;
		eventBus.unregister(this);
		overlayManager.remove(this);
		overlayManager.remove(overlayCapture);
		overlayManager.remove(draggedItemPainter);
		overlayManager.remove(draggedItemBackdrop);
		overlayManager.remove(underInterfacePainter);
		renderExecutor.shutdownNow();
		renderExecutor = null;
		rotationStorage.reset();

		RotationEditorDialog dialog = openRotationDialog;
		openRotationDialog = null;
		if (dialog != null)
			SwingUtilities.invokeLater(dialog::dispose);

		iconCacheDirectory = null;
		iconCache = null;
		renderedIcons.clear();
		referenceIcons.clear();
		resolvedStackModels.clear();
		stackModelSearchProgress.clear();
		watchedContainers.clear();
		settledContainers.clear();
		paintedThisFrame.clear();
		slots.clear();
		cutItems.clear();
		drawnUnderInterface.clear();
		dragged = null;
		draggedThisHook = null;
		backdropFrame = -1;
		patchBuffers.clear();
		patchBuffersUsed = 0;
		cachedPalette = null;
		cachedPaletteBrightness = 0;
		lastKnownBrightness = Double.NaN;
		lastKnownQuality = null;
		lastKnownCustomRotationsEnabled = true;
		lastKnownStretched = false;
		lastKnownAnimateTextures = true;
		animationCycle = 0;
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event) {
		frameCount++;
		slots.values().removeIf(slot -> slot.lastUsed < frameCount - 1);
		rendersStartedThisFrame = 0;
		paintedThisFrame.clear();
		cutItems.clear();
		drawnUnderInterface.clear();
		dragged = null;
		draggedThisHook = null;
		patchBuffersUsed = 0;

		double brightness = client.getTextureProvider().getBrightness();
		IconQuality quality = config.iconQuality();
		boolean customRotationsEnabled = config.customRotationsEnabled();
		// Icons are sharpened only when the interface is stretched, so they can't be shared
		// between the two - a sharpened icon drawn at 1:1 looks over-sharpened
		boolean stretched = client.isStretchedEnabled();
		boolean animateTextures = config.animateTextures();
		if (brightness != lastKnownBrightness || quality != lastKnownQuality
			|| customRotationsEnabled != lastKnownCustomRotationsEnabled
			|| stretched != lastKnownStretched || animateTextures != lastKnownAnimateTextures) {
			// Both the game's icons and ours depend on the brightness setting, and our own
			// renders depend on the configured supersampling quality
			lastKnownBrightness = brightness;
			lastKnownQuality = quality;
			lastKnownCustomRotationsEnabled = customRotationsEnabled;
			lastKnownStretched = stretched;
			lastKnownAnimateTextures = animateTextures;
			referenceIcons.clear();
			renderedIcons.clear();
			settledContainers.clear();
			iconCache = iconCacheDirectory == null ? null
				: new ItemIconCache(iconCacheDirectory, quality, brightness, customRotationsEnabled, stretched, animateTextures, PATCH_SIZE);
			if (iconCache != null)
				renderExecutor.execute(iconCache::markUsed);
		}

		animationCycle = client.getGameCycle();
		// Every frame, so icons are prepared as soon as the game sends the items, not once an interface shows them
		prefetchQueuedContainers();
	}

	/**
	 * Points the icon at the frame its animation is up to. The frames are rendered once and kept,
	 * so this is all an animated icon costs per frame of the game's.
	 */
	private void showAnimationFrame(RenderedIcon icon) {
		int[][] frames = icon.frames;
		if (frames == null || frames.length == 1 || icon.period < 1)
			return;

		int frame = Math.floorMod(animationCycle, icon.period) * frames.length / icon.period;
		if (frame == icon.shownFrame)
			return;

		icon.shownFrame = frame;
		icon.outlineRing = icon.frameRings[frame];
		icon.pixels = frames[frame];
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		watchedContainers.put(event.getContainerId(), event.getItemContainer().getItems());
		settledContainers.remove(event.getContainerId());
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!active)
			return null;
		boolean draggedHere = placeDraggedItem();
		super.render(graphics);
		if (draggedHere)
			cutOutDraggedItem();
		return null;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
		// Placed before the rest
		if (widgetItem.getWidget() == client.getDraggedWidget())
			return;

		PlacedIcon placed = place(widgetItem);
		if (placed == null)
			return;

		BufferProvider frame = client.getBufferProvider();
		int[] framePixels = frame.getPixels();
		float opacity = (256 - widgetItem.getWidget().getOpacity()) / 256f;
		Slot slot = placed.slot;
		if (!slot.holds(placed, opacity) || !samePixels(framePixels, frame.getWidth(), placed, slot.behind)) {
			readPatch(framePixels, frame.getWidth(), placed, slot.behind);
			int shadowColor = inpaintBackground(framePixels, frame.getWidth(), placed.bounds, placed.patchArea, placed.reference);
			composeIcon(placed, shadowColor, opacity);
			slot.keep(placed, opacity);
		}
		if (client.isGpu()) {
			// Other overlays draw onto a transparent patch, so the ones that follow the game's icon can be fitted to ours
			writePatch(framePixels, frame.getWidth(), placed, EMPTY_PATCH);
			cutItems.add(placed);
		} else {
			writePatch(framePixels, frame.getWidth(), placed, placed.composed);
		}
	}

	@Nullable
	private PlacedIcon place(WidgetItem widgetItem) {
		Widget widget = widgetItem.getWidget();
		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds.width != ICON_WIDTH || bounds.height != ICON_HEIGHT)
			return null;

		int itemId = widgetItem.getId();
		int quantity = widgetItem.getQuantity();
		int quantityMode = widget.getItemQuantityMode();
		int borderWidth = widget.getBorderType();

		// Looked up once and threaded through, rather than resolving the reference icon twice
		// (once implicitly inside icon resolution, once again for compositing).
		ReferenceIcon reference = lookupReferenceIcon(itemId, quantity, quantityMode, borderWidth, true);
		if (reference == null || reference == UNRESOLVED)
			return null;
		// Selected items use the normal icon, with the game's white border around it
		boolean selected = borderWidth == 2;
		ReferenceIcon normal = selected ? lookupReferenceIcon(itemId, quantity, quantityMode, 1, true) : reference;
		if (normal == null || normal == UNRESOLVED)
			return null;
		RenderedIcon icon = iconFor(normal, itemId, quantity, Math.min(borderWidth, 1), true);
		if (icon == null || icon == PENDING || icon.pixels == null)
			return null;
		showAnimationFrame(icon);

		Rectangle onScreen = bounds.intersection(widget.getParent().getBounds());
		boolean isDragged = widget == client.getDraggedWidget();
		// Some interfaces report their items twice. The dragged item can be anywhere over the others.
		if (onScreen.isEmpty() || !isDragged && !paintedThisFrame.add(bounds))
			return null;

		BufferProvider frame = client.getBufferProvider();
		if (frame.getPixels() == null)
			return null;

		// Partly visible items stay clipped like the interface clips them
		Rectangle patchArea = !onScreen.equals(bounds) ? onScreen :
			new Rectangle(bounds.x - MARGIN, bounds.y - MARGIN, PATCH_WIDTH, PATCH_HEIGHT)
				.intersection(new Rectangle(frame.getWidth(), frame.getHeight()));
		if (patchArea.isEmpty())
			return null;

		int[] pixels = icon.pixels;
		boolean[] outlineRing = icon.outlineRing;
		if (selected) {
			if (icon.selectedFrom != pixels) {
				icon.selectedPixels = ItemIconRasterizer.withSelectionBorder(pixels, PATCH_WIDTH, PATCH_HEIGHT);
				icon.selectedOutlineRing = ItemIconRasterizer.outlineRing(icon.selectedPixels, PATCH_WIDTH, PATCH_HEIGHT);
				icon.selectedFrom = pixels;
			}
			pixels = icon.selectedPixels;
			outlineRing = icon.selectedOutlineRing;
		}

		// Dragged items move, so they're worked out every frame
		if (isDragged)
			return new PlacedIcon(bounds, patchArea, reference, pixels, outlineRing, null, nextPatchBuffer());
		Slot slot = slots.computeIfAbsent(bounds, b -> new Slot());
		slot.lastUsed = frameCount;
		return new PlacedIcon(bounds, patchArea, reference, pixels, outlineRing, slot, slot.composed);
	}

	private int[] nextPatchBuffer() {
		if (patchBuffersUsed == patchBuffers.size())
			patchBuffers.add(new int[PATCH_SIZE]);
		return patchBuffers.get(patchBuffersUsed++);
	}

	/**
	 * The game draws the dragged item as soon as the rest of its interface is drawn, so after its layer but before the
	 * interface's overlays. Where it's already there, it's taken back out before the items under it are done.
	 */
	private boolean placeDraggedItem() {
		Widget draggedWidget = client.getDraggedWidget();
		// Once a frame, even where its interface reports it twice
		if (draggedWidget == null || dragged != null)
			return false;
		for (WidgetItem widgetItem : overlayManager.getWidgetItems()) {
			if (widgetItem.getWidget() != draggedWidget)
				continue;
			PlacedIcon placed = place(widgetItem);
			if (placed == null)
				return false;
			placed.drawnByGame = nextPatchBuffer();
			Arrays.fill(placed.drawnByGame, 0);
			if (backdropFrame == frameCount && placed.bounds.equals(backdropBounds)) {
				BufferProvider frame = client.getBufferProvider();
				takeOutGameDraggedItem(frame.getPixels(), frame.getWidth(), placed, backdrop);
			}
			dragged = placed;
			return true;
		}
		return false;
	}

	private void keepBackdrop(Rectangle bounds) {
		BufferProvider frame = client.getBufferProvider();
		int[] framePixels = frame.getPixels();
		if (framePixels == null)
			return;
		Rectangle area = new Rectangle(bounds.x - MARGIN, bounds.y - MARGIN, PATCH_WIDTH, PATCH_HEIGHT)
			.intersection(new Rectangle(frame.getWidth(), frame.getHeight()));
		for (int y = area.y; y < area.y + area.height; y++)
			for (int x = area.x; x < area.x + area.width; x++)
				backdrop[patchIndex(x - bounds.x, y - bounds.y)] = framePixels[y * frame.getWidth() + x];
		backdropBounds.setBounds(bounds);
		backdropFrame = frameCount;
	}

	/**
	 * Puts back what was under the game's dragged item, and works out what the game drew from how it's half see-through.
	 * Only where the game's icon covers, so anything drawn after it stays.
	 */
	private static void takeOutGameDraggedItem(int[] framePixels, int frameWidth, PlacedIcon dragged, int[] under) {
		ReferenceIcon reference = dragged.reference;
		for (int y = dragged.patchArea.y; y < dragged.patchArea.y + dragged.patchArea.height; y++) {
			for (int x = dragged.patchArea.x; x < dragged.patchArea.x + dragged.patchArea.width; x++) {
				int i = y * frameWidth + x;
				int patch = patchIndex(x - dragged.bounds.x, y - dragged.bounds.y);
				if (framePixels[i] == under[patch] || !reference.has(patch, FLAG_ITEM)
					&& !reference.has(patch, FLAG_SHADOW) && !reference.has(patch, FLAG_STACK_TEXT))
					continue;
				dragged.drawnByGame[patch] = unblendDragged(framePixels[i], under[patch]);
				framePixels[i] = under[patch];
			}
		}
	}

	// The game draws the dragged item half see-through, and every pixel of its icon is opaque
	private static int unblendDragged(int drawn, int under) {
		int result = 0xFF000000;
		for (int shift = 0; shift < 24; shift += 8) {
			int channel = Math.round(((drawn >>> shift & 0xFF) - (under >>> shift & 0xFF) * (1 - DRAGGED_OPACITY)) / DRAGGED_OPACITY);
			result |= Math.max(0, Math.min(255, channel)) << shift;
		}
		return result;
	}

	private void cutOutDraggedItem() {
		PlacedIcon placed = dragged;
		if (placed == null)
			return;
		if (client.isGpu()) {
			// Drawn under everything, since the game draws the dragged item over the rest of the interface
			BufferProvider frame = client.getBufferProvider();
			int[] framePixels = frame.getPixels();
			int frameWidth = frame.getWidth();
			placed.background = nextPatchBuffer();
			readPatch(framePixels, frameWidth, placed, placed.background);
			for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
				int row = y * frameWidth + placed.patchArea.x;
				Arrays.fill(framePixels, row, row + placed.patchArea.width, 0);
			}
		}
		draggedThisHook = placed;
	}

	private void drawDraggedItem() {
		PlacedIcon placed = dragged;
		if (placed == null || placed.background == null)
			return;

		BufferProvider frame = client.getBufferProvider();
		int[] framePixels = frame.getPixels();
		int frameWidth = frame.getWidth();
		boolean gpu = client.isGpu();
		boolean foundEarlier = false;
		for (int pixel : placed.drawnByGame)
			foundEarlier |= pixel != 0;
		if (!foundEarlier) {
			// With GPU what it's drawn over is cut out
			takeOutGameDraggedItem(framePixels, frameWidth, placed, gpu ? EMPTY_PATCH : placed.background);
		}

		int shadowColor = 0;
		for (int patch = 0; patch < PATCH_SIZE; patch++) {
			if (placed.drawnByGame[patch] != 0 && placed.reference.has(patch, FLAG_SHADOW) && !placed.reference.has(patch, FLAG_STACK_TEXT)) {
				shadowColor = scale(placed.drawnByGame[patch], DRAGGED_OPACITY);
				break;
			}
		}
		if (gpu)
			Arrays.fill(patchColor, 0);
		else
			System.arraycopy(placed.background, 0, patchColor, 0, PATCH_SIZE);
		composeIcon(placed, shadowColor, DRAGGED_OPACITY);
		int[] drawn = drawWithOverlays(placed);
		// Its count, as the game drew it
		for (int patch = 0; patch < PATCH_SIZE; patch++)
			if (placed.drawnByGame[patch] != 0 && placed.reference.has(patch, FLAG_STACK_TEXT))
				drawn[patch] = over(scale(placed.drawnByGame[patch], DRAGGED_OPACITY), drawn[patch]);

		if (gpu) {
			placed.drawn = drawn;
			return;
		}
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++)
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++)
				framePixels[y * frameWidth + x] = drawn[patchIndex(x - placed.bounds.x, y - placed.bounds.y)];
	}

	/**
	 * The dragged item goes over the items, newest first, and what the dragged item is drawn over goes under them all.
	 */
	private void drawUnderInterface() {
		BufferProvider frame = client.getBufferProvider();
		int[] framePixels = frame.getPixels();
		if (framePixels == null || !client.isGpu()) {
			drawnUnderInterface.clear();
			return;
		}
		int frameWidth = frame.getWidth();
		PlacedIcon placed = dragged;
		boolean draggedDrawn = placed != null && placed.drawn != null;
		if (draggedDrawn)
			drawUnder(framePixels, frameWidth, placed, placed.drawn);
		for (int i = drawnUnderInterface.size() - 1; i >= 0; i--) {
			PlacedIcon item = drawnUnderInterface.get(i);
			drawUnder(framePixels, frameWidth, item, item.drawn);
		}
		drawnUnderInterface.clear();
		if (draggedDrawn)
			drawUnder(framePixels, frameWidth, placed, placed.background);
	}

	private static void drawUnder(int[] framePixels, int frameWidth, PlacedIcon placed, int[] patchPixels) {
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int i = y * frameWidth + x;
				int above = framePixels[i];
				if (above >>> 24 == 0xFF)
					continue;
				int ours = patchPixels[patchIndex(x - placed.bounds.x, y - placed.bounds.y)];
				framePixels[i] = above == 0 ? ours : over(above, ours);
			}
		}
	}

	@Nullable
	private RenderedIcon resolveIcon(int itemId, int quantity, int quantityMode, int borderWidth, boolean visibleNow) {
		ReferenceIcon reference = lookupReferenceIcon(itemId, quantity, quantityMode, borderWidth, visibleNow);
		if (reference == UNRESOLVED)
			return PENDING;
		if (reference == null)
			return null;
		return iconFor(reference, itemId, quantity, borderWidth, visibleNow);
	}

	@Nullable
	private RenderedIcon iconFor(ReferenceIcon reference, int itemId, int quantity, int borderWidth, boolean visibleNow) {
		RenderedIcon icon = renderedIcons.get(reference.fingerprint);
		if (icon == null) {
			if (!consumeRenderBudget(visibleNow))
				return PENDING;

			icon = new RenderedIcon();
			icon.itemId = itemId;
			renderedIcons.put(reference.fingerprint, icon);
			if (iconCache != null) {
				loadIcon(icon, iconCache, reference.fingerprint);
				return icon;
			}
			icon.uncached = true;
		}
		if (icon.uncached) {
			if (!consumeRenderBudget(visibleNow))
				return PENDING;

			int modelItemId = resolveModelItemId(itemId, quantity, borderWidth, reference);
			if (modelItemId == -1)
				return PENDING;
			icon.uncached = false;
			if (modelItemId == -2) {
				icon.failed = true;
				ItemIconCache cache = iconCache;
				if (cache != null)
					renderExecutor.execute(() -> cache.save(reference.fingerprint, 0, null));
			} else {
				beginRenderingIcon(icon, modelItemId, borderWidth, reference.fingerprint);
			}
		}
		return icon.failed ? null : icon;
	}

	private void loadIcon(RenderedIcon icon, ItemIconCache cache, long fingerprint) {
		renderExecutor.execute(() -> {
			ItemIconCache.Kept kept = cache.load(fingerprint);
			if (kept == null)
				icon.uncached = true;
			else if (kept.frames.length == 0)
				icon.failed = true;
			else
				publishFrames(icon, kept.period, kept.frames);
		});
	}

	private static void publishFrames(RenderedIcon icon, int period, int[][] frames) {
		boolean[][] rings = new boolean[frames.length][];
		for (int frame = 0; frame < frames.length; frame++)
			rings[frame] = ItemIconRasterizer.outlineRing(frames[frame], PATCH_WIDTH, PATCH_HEIGHT);

		icon.frameRings = rings;
		icon.period = period;
		icon.frames = frames;
		icon.outlineRing = rings[0];
		icon.pixels = frames[0];
	}

	private boolean consumeRenderBudget(boolean visibleNow) {
		if (!visibleNow && rendersStartedThisFrame >= MAX_NEW_RENDERS_PER_FRAME)
			return false;
		rendersStartedThisFrame++;
		return true;
	}

	/**
	 * Starts a render for every not-yet-settled container's items ahead of time, so icons are
	 * usually already rendered by the time the player actually looks at them (e.g. scrolling
	 * the bank). Bounded by the same per-frame budget as on-screen items.
	 */
	private void prefetchQueuedContainers() {
		// What's carried and worn stays ready, even while it isn't shown or the cache is full
		for (int containerId : KEPT_CONTAINERS) {
			Item[] items = watchedContainers.get(containerId);
			if (items == null)
				continue;
			for (Item item : items) {
				if (item.getId() != -1)
					resolveIcon(item.getId(), item.getQuantity(), ItemQuantityMode.NEVER, 1, false);
			}
		}

		for (Map.Entry<Integer, Item[]> entry : watchedContainers.entrySet()) {
			int containerId = entry.getKey();
			if (settledContainers.contains(containerId))
				continue;

			boolean settled = true;
			for (Item item : entry.getValue()) {
				if (renderedIcons.size() >= MAX_CACHED_ICONS)
					return;
				if (item.getId() == -1)
					continue;
				RenderedIcon icon = resolveIcon(item.getId(), item.getQuantity(), ItemQuantityMode.NEVER, 1, false);
				// A stack whose model is still being searched for doesn't hold up the rest
				if (icon == PENDING && rendersStartedThisFrame >= MAX_NEW_RENDERS_PER_FRAME)
					return;
				settled &= icon == null || icon.pixels != null;
			}
			if (settled)
				settledContainers.add(containerId);
		}
	}

	@Nullable
	private ReferenceIcon lookupReferenceIcon(int itemId, int quantity, int quantityMode, int borderWidth, boolean visibleNow) {
		long key = (long) quantity << 24 | (long) itemId << 4 | (long) quantityMode << 2 | borderWidth;
		ReferenceIcon cached = referenceIcons.get(key);
		if (cached != null || referenceIcons.containsKey(key))
			return cached;
		if (!consumeRenderBudget(visibleNow))
			return UNRESOLVED;

		ReferenceIcon reference = null;
		int[] plain = fetchGamePixels(itemId, quantity, borderWidth, ItemQuantityMode.NEVER, false);
		int[] withCount = plain == null || quantityMode == ItemQuantityMode.NEVER ? plain :
			fetchGamePixels(itemId, quantity, borderWidth, quantityMode, false);
		if (withCount != null)
			reference = new ReferenceIcon(itemId, borderWidth, config.iconQuality().getSupersample(), plain, withCount);
		referenceIcons.put(key, reference);
		return reference;
	}

	// Stacks like coins and arrows show the model of an unnamed item, which the API doesn't expose
	private int resolveModelItemId(int itemId, int quantity, int borderWidth, ReferenceIcon reference) {
		if (reference.resolvedModelItemId != -1)
			return reference.resolvedModelItemId;

		ItemComposition definition = client.getItemDefinition(itemId);
		if (definition.getPlaceholderTemplateId() != -1) {
			reference.resolvedModelItemId = definition.getPlaceholderId();
		} else if (quantity == 1 || Arrays.equals(reference.plainPixels, fetchGamePixels(itemId, 1, borderWidth, ItemQuantityMode.NEVER, false))) {
			reference.resolvedModelItemId = itemId;
		} else {
			return searchForStackModelItem(itemId, borderWidth, reference.plainPixels);
		}
		return reference.resolvedModelItemId;
	}

	/**
	 * Some stackable items (coins, arrows, ...) share a model belonging to a different,
	 * unnamed item id that isn't otherwise discoverable. We search outward from the item's own
	 * id for one whose plain icon pixels match, a few candidates per frame, remembering how
	 * far we've searched so a large search resumes instead of restarting.
	 */
	private int searchForStackModelItem(int itemId, int borderWidth, int[] targetPixels) {
		long key = (long) Arrays.hashCode(targetPixels) << 32 | (long) itemId << 2 | borderWidth;
		Integer resolved = resolvedStackModels.get(key);
		if (resolved != null)
			return resolved == -1 ? -2 : resolved;

		int totalItems = client.getItemCount();
		int distance = stackModelSearchProgress.getOrDefault(key, 0);
		for (int checked = 0; checked < 256 && rendersStartedThisFrame < MAX_NEW_RENDERS_PER_FRAME; checked++) {
			distance++;
			if (itemId + distance / 2 >= totalItems && itemId - distance / 2 < 0) {
				resolvedStackModels.put(key, -1);
				stackModelSearchProgress.remove(key);
				return -2;
			}
			int candidate = itemId + (distance % 2 == 1 ? distance / 2 + 1 : -distance / 2);
			if (candidate < 0 || candidate >= totalItems || !"null".equals(client.getItemDefinition(candidate).getName()))
				continue;
			rendersStartedThisFrame++;
			if (Arrays.equals(targetPixels, fetchGamePixels(candidate, 1, borderWidth, ItemQuantityMode.NEVER, false))) {
				resolvedStackModels.put(key, candidate);
				stackModelSearchProgress.remove(key);
				return candidate;
			}
		}
		stackModelSearchProgress.put(key, distance);
		return -1;
	}

	@Nullable
	private int[] fetchGamePixels(int itemId, int quantity, int borderWidth, int quantityMode, boolean noted) {
		var sprite = client.createItemSprite(itemId, quantity, borderWidth, 0, quantityMode, noted, Constants.CLIENT_DEFAULT_ZOOM);
		return sprite == null ? null : sprite.getPixels();
	}

	private void beginRenderingIcon(RenderedIcon icon, int itemId, int borderWidth, long fingerprint) {
		ItemComposition item = client.getItemDefinition(itemId);
		// Notes are drawn as the note's paper with a small copy of the real item on top
		ModelLayer[] layers = item.getNote() == -1
			? new ModelLayer[]{buildModelLayer(itemId, 1, false, borderWidth)}
			: new ModelLayer[]{buildModelLayer(item.getNote(), 1, false, borderWidth), buildModelLayer(item.getLinkedNoteId(), 10, true, 1)};
		for (ModelLayer layer : layers) {
			if (layer == null) {
				icon.failed = true;
				return;
			}
		}

		double brightness = lastKnownBrightness;
		int supersample = config.iconQuality().getSupersample();
		boolean sharpen = lastKnownStretched;
		ItemIconCache cache = iconCache;
		int period = lastKnownAnimateTextures ? animationPeriodOf(layers) : 0;
		int animationFrames = period < 2 ? 1 : Math.min(period, MAX_ANIMATION_FRAMES);
		renderExecutor.execute(() -> {
			try {
				int[] palette = paletteFor(brightness);
				ItemIconRasterizer[] rasterizers = new ItemIconRasterizer[layers.length];
				boolean[] outlined = new boolean[layers.length];
				for (int i = 0; i < layers.length; i++) {
					ModelLayer layer = layers[i];
					CustomRotation placement = layer.placement;
					ItemIconRasterizer rasterizer = placement == null
						? new ItemIconRasterizer(layer.model, layer.pitchJau, layer.yawJau, layer.rollJau, supersample)
						: new ItemIconRasterizer(layer.model, layer.pitchJau, layer.yawJau, layer.rollJau,
							placement.resizeX, placement.resizeY, placement.resizeZ, supersample);
					rasterizers[i] = rasterizer;
					outlined[i] = layer.borderWidth > 0;
					rasterizer.animateTo(0);
					if (placement != null) {
						rasterizer.placeExplicitly(placement.zoom2d, placement.offsetX, placement.offsetY);
					} else if (!rasterizer.fitToReferenceSilhouette(layer.referencePixels, palette)) {
						icon.failed = true;
						if (cache != null)
							cache.save(fingerprint, 0, null);
						return;
					}
				}

				int[][] frames = new int[animationFrames][];
				for (int frame = 0; frame < animationFrames; frame++) {
					int[] combined = null;
					for (int i = 0; i < rasterizers.length; i++) {
						rasterizers[i].animateTo(frame * period / animationFrames);
						int[] rendered = rasterizers[i].render(MARGIN, outlined[i], sharpen, palette);
						combined = combined == null ? rendered : ItemIconRasterizer.compositeOver(rendered, combined);
					}
					frames[frame] = combined;
					// Shown as a still icon while the rest of its animation renders
					if (frame == 0 && animationFrames > 1) {
						icon.outlineRing = ItemIconRasterizer.outlineRing(combined, PATCH_WIDTH, PATCH_HEIGHT);
						icon.pixels = combined;
					}
				}

				publishFrames(icon, period, frames);
				if (cache != null)
					cache.save(fingerprint, period, frames);
			} catch (Throwable ex) {
				log.debug("Unable to render an HD icon for item {}:", itemId, ex);
				icon.failed = true;
			}
		});
	}

	private static int animationPeriodOf(ModelLayer[] layers) {
		int period = 0;
		for (ModelLayer layer : layers)
			period = Math.max(period, layer.model.animationPeriod);
		return period;
	}

	@Nullable
	private ModelLayer buildModelLayer(int itemId, int quantity, boolean noted, int borderWidth) {
		ItemComposition item = client.getItemDefinition(itemId);
		ItemIconRasterizer.IconModel iconModel = captureModel(item);
		int[] referencePixels = fetchGamePixels(itemId, quantity, 0, ItemQuantityMode.NEVER, noted);
		if (iconModel == null || referencePixels == null)
			return null;

		CustomRotation override = config.customRotationsEnabled() ? rotationStorage.get(itemId) : null;
		int pitch = override != null ? override.xan2d : item.getXan2d();
		int yaw = override != null ? override.yan2d : item.getYan2d();
		int roll = override != null ? override.zan2d : item.getZan2d();
		return new ModelLayer(iconModel, pitch, yaw, roll, referencePixels, borderWidth, override);
	}

	@Nullable
	private ItemIconRasterizer.IconModel captureModel(ItemComposition item) {
		ModelData data = client.loadModelData(item.getInventoryModel());
		if (data == null)
			return null;

		short[] colorFind = item.getColorToReplace();
		short[] colorReplace = item.getColorToReplaceWith();
		if (colorFind != null) {
			data = data.cloneColors();
			for (int i = 0; i < colorFind.length; i++)
				data.recolor(colorFind[i], colorReplace[i]);
		}

		short[] textureFind = item.getTextureToReplace();
		short[] textureReplace = item.getTextureToReplaceWith();
		if (textureFind != null) {
			data = data.cloneTextures();
			for (int i = 0; i < textureFind.length; i++)
				data.retexture(textureFind[i], textureReplace[i]);
		}

		// Lit the same way the game lights item models for its own icons
		Model litModel = data.light(item.getAmbient() + 64, item.getContrast() + 768, -50, -10, -50);
		return ItemIconRasterizer.IconModel.capture(litModel, client.getTextureProvider());
	}

	/** Called from the menu entry's click handler, which already runs on the client thread. */
	public void openRotationEditor(int itemId) {
		if (!active || Double.isNaN(lastKnownBrightness))
			return;

		ItemComposition item = client.getItemDefinition(itemId);
		ItemIconRasterizer.IconModel iconModel = captureModel(item);
		if (iconModel == null)
			return;

		int[] palette = paletteFor(lastKnownBrightness);
		int supersample = config.iconQuality().getSupersample();

		ItemRenderSheet.Placement sheetDefault = itemRenderSheet.get(itemId);
		CustomRotation defaults = new CustomRotation(item.getXan2d(), item.getYan2d(), item.getZan2d(),
			sheetDefault.zoom2d, sheetDefault.offsetX, sheetDefault.offsetY,
			sheetDefault.resizeX, sheetDefault.resizeY, sheetDefault.resizeZ);
		CustomRotation existing = rotationStorage.get(itemId);
		CustomRotation initial = existing != null ? existing : defaults;
		String name = item.getName();
		List<RotationEditorDialog.Preset> presets = savedIconPresets(itemId);
		int[] referencePixels = fetchGamePixels(itemId, 1, 0, ItemQuantityMode.NEVER, false);

		SwingUtilities.invokeLater(() -> {
			if (!active)
				return;
			RotationEditorDialog dialog = new RotationEditorDialog(name, itemId, initial, defaults, presets,
				iconModel, referencePixels, palette, supersample, rotationStorage, this::onRotationChanged);
			openRotationDialog = dialog;
			dialog.setVisible(true);
		});
	}

	/**
	 * Every other item with a saved rotation, to be offered as presets to copy. Client thread
	 * only, for the item names.
	 */
	private List<RotationEditorDialog.Preset> savedIconPresets(int editingItemId) {
		List<RotationEditorDialog.Preset> presets = new ArrayList<>();
		int itemCount = client.getItemCount();
		for (Map.Entry<Integer, CustomRotation> saved : rotationStorage.all().entrySet()) {
			int itemId = saved.getKey();
			// A saved id can outlive the item, if the game's cache changed under it
			if (itemId == editingItemId || itemId < 0 || itemId >= itemCount)
				continue;
			String name = client.getItemDefinition(itemId).getName();
			if (name == null || name.isEmpty() || "null".equals(name))
				name = "Item";
			presets.add(new RotationEditorDialog.Preset(name + " (" + itemId + ")", saved.getValue()));
		}
		presets.sort(Comparator.comparing(Object::toString, String.CASE_INSENSITIVE_ORDER));
		return presets;
	}

	private void onRotationChanged(int itemId) {
		clientThread.invoke(() -> clearRenderCache(itemId));
	}

	/** The cache is keyed by the game's own icon, which a saved rotation doesn't change. */
	public void clearRenderCache(int itemId) {
		clearRenderCache(Set.of(itemId));
	}

	public void clearRenderCache(Collection<Integer> itemIds) {
		if (itemIds.isEmpty())
			return;

		Set<Integer> targets = Set.copyOf(itemIds);
		List<Long> cleared = new ArrayList<>();
		renderedIcons.replaceAll((fingerprint, icon) -> {
			if (!targets.contains(icon.itemId))
				return icon;
			cleared.add(fingerprint);
			return renderAgain(icon);
		});
		deleteCachedImages(cleared);
	}

	public void clearRenderCache() {
		List<Long> cleared = new ArrayList<>(renderedIcons.keySet());
		renderedIcons.replaceAll((fingerprint, icon) -> renderAgain(icon));
		settledContainers.clear();
		deleteCachedImages(cleared);
	}

	// Not loaded from disk, where the old icon may not be deleted yet
	private static RenderedIcon renderAgain(RenderedIcon icon) {
		RenderedIcon fresh = new RenderedIcon();
		fresh.itemId = icon.itemId;
		fresh.uncached = true;
		return fresh;
	}

	private void deleteCachedImages(List<Long> fingerprints) {
		ItemIconCache cache = iconCache;
		ExecutorService executor = renderExecutor;
		if (cache == null || executor == null || fingerprints.isEmpty())
			return;

		executor.execute(() -> {
			for (long fingerprint : fingerprints)
				cache.delete(fingerprint);
		});
	}

	private synchronized int[] paletteFor(double brightness) {
		if (cachedPalette == null || cachedPaletteBrightness != brightness) {
			cachedPalette = ItemIconRasterizer.buildPalette(brightness);
			cachedPaletteBrightness = brightness;
		}
		return cachedPalette;
	}

	/**
	 * Reads the frame pixels under {@code patchArea} into {@link #patchColor}, then replaces
	 * every pixel the game's icon covers with a plausible background inpainted from what
	 * surrounds it, so our own antialiased edges blend onto something sensible instead of the
	 * old icon. Returns the colour the game shaded its own drop shadow with, or 0 if the
	 * shadow pixels don't all share one colour (a busy background), in which case we skip
	 * drawing a shadow of our own.
	 */
	private int inpaintBackground(int[] framePixels, int frameWidth, Rectangle iconBounds, Rectangle patchArea, ReferenceIcon reference) {
		Arrays.fill(patchColor, 0);
		Arrays.fill(patchResolved, false);
		for (int y = patchArea.y; y < patchArea.y + patchArea.height; y++) {
			for (int x = patchArea.x; x < patchArea.x + patchArea.width; x++) {
				int patch = patchIndex(x - iconBounds.x, y - iconBounds.y);
				patchColor[patch] = framePixels[y * frameWidth + x];
				patchResolved[patch] = !reference.has(patch, FLAG_ITEM) && !reference.has(patch, FLAG_STACK_TEXT);
			}
		}

		// Detected first, since it samples the pixels the loop below marks for inpainting
		int shadowColor = detectUniformShadowColor(reference);
		// The game's shadow goes whether or not its colour could be identified: a colour we can't
		// match means we draw no shadow of our own, not that we keep theirs. Leaving it behind
		// only stays hidden while our icon covers it, so a custom rotation exposes it as a fringe.
		for (int patch = 0; patch < PATCH_SIZE; patch++)
			if (reference.has(patch, FLAG_SHADOW))
				patchResolved[patch] = false;

		// Each pass only reaches one pixel further in, and the pixels it hasn't reached still hold
		// the game's icon, so this runs until the whole silhouette is covered rather than to a
		// fixed budget. Stopping early left the middle of the icon in place, which only stayed
		// hidden while ours covered the same shape - a custom rotation exposes it.
		for (int pass = 0; pass < INPAINT_PASSES; pass++)
			if (!spreadKnownColorsOnce())
				break;

		return shadowColor;
	}

	/** Every pixel the game drop-shadowed should be the same colour; if not, treat as unknown. */
	private int detectUniformShadowColor(ReferenceIcon reference) {
		int shadowColor = 0;
		boolean seenAny = false;
		for (int patch = 0; patch < PATCH_SIZE; patch++) {
			if (!patchResolved[patch] || !reference.has(patch, FLAG_SHADOW))
				continue;
			if (!seenAny) {
				shadowColor = patchColor[patch];
				seenAny = true;
			} else if (patchColor[patch] != shadowColor) {
				return 0;
			}
		}
		return shadowColor;
	}

	/**
	 * One diffusion pass: every unresolved pixel adopts the average of its resolved
	 * neighbours. Returns whether anything was actually resolved this pass, so the caller can
	 * stop early once the patch has settled instead of always running the full pass budget.
	 */
	private boolean spreadKnownColorsOnce() {
		System.arraycopy(patchResolved, 0, patchResolvedScratch, 0, PATCH_SIZE);
		boolean resolvedAny = false;
		int patch = 0;
		for (int y = 0; y < PATCH_HEIGHT; y++) {
			for (int x = 0; x < PATCH_WIDTH; x++, patch++) {
				if (patchResolved[patch])
					continue;

				int count = 0, a = 0, r = 0, g = 0, b = 0;
				for (int n = 0; n < NEIGHBOR_DX.length; n++) {
					int nx = x + NEIGHBOR_DX[n];
					int ny = y + NEIGHBOR_DY[n];
					if (nx < 0 || nx >= PATCH_WIDTH || ny < 0 || ny >= PATCH_HEIGHT)
						continue;
					int neighborPatch = ny * PATCH_WIDTH + nx;
					if (!patchResolved[neighborPatch])
						continue;
					int neighborColor = patchColor[neighborPatch];
					a += neighborColor >>> 24;
					r += neighborColor >> 16 & 0xFF;
					g += neighborColor >> 8 & 0xFF;
					b += neighborColor & 0xFF;
					count++;
				}
				if (count > 0) {
					patchColor[patch] = (a / count) << 24 | (r / count) << 16 | (g / count) << 8 | (b / count);
					patchResolvedScratch[patch] = true;
					resolvedAny = true;
				}
			}
		}
		System.arraycopy(patchResolvedScratch, 0, patchResolved, 0, PATCH_SIZE);
		return resolvedAny;
	}

	private void composeIcon(PlacedIcon placed, int shadowColor, float opacity) {
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int localX = x - placed.bounds.x;
				int localY = y - placed.bounds.y;
				int patch = patchIndex(localX, localY);
				int background = patchColor[patch];
				if (shadowColor != 0 && localX - 1 >= -MARGIN && localY - 1 >= -MARGIN) {
					float shade = alpha(placed.pixels[patchIndex(localX - 1, localY - 1)]);
					background = blend(shadowColor, shade, background, 1 - alpha(shadowColor) * shade);
				}

				// With GPU the interface is premultiplied ARGB, so alpha is blended like the colours
				int iconArgb = placed.pixels[patch];
				placed.composed[patch] = blend(iconArgb, opacity, background, 1 - alpha(iconArgb) * opacity);
			}
		}
	}

	private static void writePatch(int[] framePixels, int frameWidth, PlacedIcon placed, int[] patchPixels) {
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int patch = patchIndex(x - placed.bounds.x, y - placed.bounds.y);
				if (!placed.reference.has(patch, FLAG_STACK_TEXT))
					framePixels[y * frameWidth + x] = patchPixels[patch];
			}
		}
	}

	private static boolean samePixels(int[] framePixels, int frameWidth, PlacedIcon placed, int[] patchPixels) {
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			int i = y * frameWidth + placed.patchArea.x;
			int patch = patchIndex(placed.patchArea.x - placed.bounds.x, y - placed.bounds.y);
			if (!Arrays.equals(framePixels, i, i + placed.patchArea.width, patchPixels, patch, patch + placed.patchArea.width))
				return false;
		}
		return true;
	}

	private static boolean samePatch(PlacedIcon placed, int[] a, int[] b) {
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			int patch = patchIndex(placed.patchArea.x - placed.bounds.x, y - placed.bounds.y);
			if (!Arrays.equals(a, patch, patch + placed.patchArea.width, b, patch, patch + placed.patchArea.width))
				return false;
		}
		return true;
	}

	private static void readPatch(int[] framePixels, int frameWidth, PlacedIcon placed, int[] patchPixels) {
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++)
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++)
				patchPixels[patchIndex(x - placed.bounds.x, y - placed.bounds.y)] = framePixels[y * frameWidth + x];
	}

	/**
	 * Takes what other overlays drew over the cut out item. Fills and outlines that follow the game's icon, like
	 * Inventory Tags', are redrawn to fit ours, with fills covering the shadow too. Everything else stays where it was
	 * drawn, unless it's all taken.
	 */
	private void captureOverlays(int[] framePixels, int frameWidth, PlacedIcon placed) {
		// Nothing was drawn over the item while its pixels are still as they were cut out
		if (!placed.takeAll && placed.slot != null && samePixels(framePixels, frameWidth, placed, placed.slot.cut)) {
			placed.overlays = null;
			return;
		}
		ReferenceIcon reference = placed.reference;
		placed.overlays = nextPatchBuffer();
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int patch = patchIndex(x - placed.bounds.x, y - placed.bounds.y);
				placed.overlays[patch] = !placed.takeAll && reference.has(patch, FLAG_STACK_TEXT) ? 0 : framePixels[y * frameWidth + x];
			}
		}
		placed.fill = shapeColor(placed, FLAG_ITEM);
		placed.outline = shapeColor(placed, FLAG_OUTLINE);
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int patch = patchIndex(x - placed.bounds.x, y - placed.bounds.y);
				if (placed.takeAll || isRedrawn(placed, patch))
					framePixels[y * frameWidth + x] = 0;
			}
		}
	}

	private static boolean isRedrawn(PlacedIcon placed, int patch) {
		ReferenceIcon reference = placed.reference;
		int overlay = placed.overlays[patch];
		return !reference.has(patch, FLAG_STACK_TEXT) && (
			placed.fill != 0 && (reference.has(patch, FLAG_ITEM) && overlay == placed.fill || reference.has(patch, FLAG_SHADOW)) ||
			placed.outline != 0 && reference.has(patch, FLAG_OUTLINE) && overlay == placed.outline);
	}

	private int[] drawWithOverlays(PlacedIcon placed) {
		Slot slot = placed.slot;
		if (placed.overlays == null)
			return placed.composed;
		if (slot != null && slot.overlaid && slot.takeAll == placed.takeAll && samePatch(placed, placed.overlays, slot.overlays))
			return slot.drawn;

		int fill = placed.fill;
		int outline = placed.outline;
		int[] drawn = slot != null ? slot.drawn : nextPatchBuffer();
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int localX = x - placed.bounds.x;
				int localY = y - placed.bounds.y;
				int patch = patchIndex(localX, localY);
				// What isn't taken stays in the interface, over ours
				int overlay = placed.takeAll && !isRedrawn(placed, patch) ? placed.overlays[patch] : 0;
				float item = alpha(placed.pixels[patch]);
				float shadow = localX - 1 >= -MARGIN && localY - 1 >= -MARGIN ? alpha(placed.pixels[patchIndex(localX - 1, localY - 1)]) : 0;
				float outlined = placed.outlineRing[patch] ? 1 - item : 0;
				int fitted = over(scale(fill, Math.max(item, shadow)), scale(outline, outlined));
				drawn[patch] = over(over(overlay, fitted), placed.composed[patch]);
			}
		}
		if (slot != null) {
			System.arraycopy(placed.overlays, 0, slot.overlays, 0, PATCH_SIZE);
			slot.overlaid = true;
			slot.takeAll = placed.takeAll;
		}
		return drawn;
	}

	private static int shapeColor(PlacedIcon placed, byte shape) {
		ReferenceIcon reference = placed.reference;
		// Boyer-Moore majority vote
		int color = 0, lead = 0, pixels = 0;
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int patch = patchIndex(x - placed.bounds.x, y - placed.bounds.y);
				if (reference.has(patch, FLAG_STACK_TEXT) || !reference.has(patch, shape) || reference.has(patch, FLAG_SHADOW))
					continue;
				pixels++;
				if (lead == 0)
					color = placed.overlays[patch];
				lead += placed.overlays[patch] == color ? 1 : -1;
			}
		}
		if (color == 0)
			return 0;

		int covered = 0;
		for (int y = placed.patchArea.y; y < placed.patchArea.y + placed.patchArea.height; y++) {
			for (int x = placed.patchArea.x; x < placed.patchArea.x + placed.patchArea.width; x++) {
				int patch = patchIndex(x - placed.bounds.x, y - placed.bounds.y);
				if (reference.has(patch, FLAG_STACK_TEXT) || placed.overlays[patch] != color || reference.has(patch, FLAG_SHADOW))
					continue;
				if (!reference.has(patch, shape))
					return 0;
				covered++;
			}
		}
		return covered >= MIN_SHAPE_COVERAGE * pixels ? color : 0;
	}

	private static float alpha(int argb) {
		return (argb >>> 24) / 255f;
	}

	private static int scale(int argb, float factor) {
		return blend(argb, factor, 0, 0);
	}

	private static int over(int top, int bottom) {
		return blend(top, 1, bottom, 1 - alpha(top));
	}

	private static int blend(int top, float topWeight, int bottom, float bottomWeight) {
		int result = 0;
		for (int shift = 0; shift < 32; shift += 8) {
			int channel = Math.round((top >>> shift & 0xFF) * topWeight + (bottom >>> shift & 0xFF) * bottomWeight);
			result |= Math.min(255, channel) << shift;
		}
		return result;
	}
}

package io.mark.hditemicons.hd;


final class IconMath {

	static final double TURN = 2048;

	static int floorToInt(double v) {
		return (int) Math.floor(v);
	}

	static int ceilToInt(double v) {
		return (int) Math.ceil(v);
	}

	static int clampInt(int v, int lo, int hi) {
		return v < lo ? lo : Math.min(v, hi);
	}

	static double clampDouble(double v, double lo, double hi) {
		return v < lo ? lo : Math.min(v, hi);
	}

	static int wrap(int v, int modulus) {
		int r = v % modulus;
		return r < 0 ? r + modulus : r;
	}

	/**
	 * Packed-HSL layout: bits 15-10 hue (6 bits), 9-7 saturation (3 bits), 6-0 lightness
	 * (7 bits). Each band is offset by half a quantisation step so it decodes to the centre of
	 * the band rather than its low edge. Returns linear-order sRGB components in 0..1.
	 */
	static double[] decodeHsl(int packed) {
		double hue = ((packed >>> 10) & 0x3F) / 64.0 + 1.0 / 128;
		double sat = ((packed >>> 7) & 0x7) / 8.0 + 1.0 / 16;
		double lum = (packed & 0x7F) / 128.0;

		double chroma = sat * (1 - Math.abs(2 * lum - 1));
		double h6 = (hue - Math.floor(hue)) * 6;
		double mid = lum - chroma / 2;

		double r = clampDouble(Math.abs(h6 - 3) - 1, 0, 1) * chroma + mid;
		double g = clampDouble(2 - Math.abs(h6 - 2), 0, 1) * chroma + mid;
		double b = clampDouble(2 - Math.abs(h6 - 4), 0, 1) * chroma + mid;
		return new double[]{r, g, b};
	}
}

package io.mark.hditemicons.hd;

import io.mark.hditemicons.IconQuality;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.file.NoSuchFileException;
import java.nio.file.attribute.FileTime;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import java.util.zip.DeflaterOutputStream;
import java.util.zip.InflaterInputStream;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import static java.nio.file.StandardCopyOption.ATOMIC_MOVE;
import static java.nio.file.StandardCopyOption.REPLACE_EXISTING;

/**
 * Rendered icons kept on disk, in a folder per icon quality and brightness, and apart when custom rotations are off or
 * the interface is stretched.
 */
@Slf4j
class ItemIconCache {
	// Bump when icons are drawn differently
	private static final int VERSION = 6;
	private static final int MAX_FOLDERS = 3;
	private static final int HEADER_INTS = 2;

	private final Filepath folder;
	private final int size;

	ItemIconCache(Filepath root, IconQuality quality, double brightness, boolean customRotations, boolean stretched,
				boolean animatedTextures, int size) {
		folder = root.joinSegment(String.format(Locale.ROOT, "v%d-%s-%.3f%s%s%s", VERSION, quality.name().toLowerCase(Locale.ROOT), brightness,
			customRotations ? "" : "-default-rotations", stretched ? "-stretched" : "", animatedTextures ? "" : "-static-textures"));
		this.size = size;
	}

	/**
	 * An icon as it was kept: one frame per phase of its animation, and the length of that
	 * animation in client cycles. A still icon is one frame with no period.
	 */
	static final class Kept {
		final int period;
		final int[][] frames;

		Kept(int period, int[][] frames) {
			this.period = period;
			this.frames = frames;
		}
	}

	void markUsed() {
		try {
			// Creating a file updates the folder's modification time
			if (folder.isDirectory())
				folder.createTempFile("used", ".tmp").delete();
		} catch (IOException ex) {
			log.debug("Unable to mark item icons as used:", ex);
		}
	}

	/**
	 * The icon's frames, no frames if it couldn't be rendered, or null if it isn't kept.
	 */
	@Nullable
	Kept load(long key) {
		try {
			byte[] file;
			try (var in = folder.joinSegment(fileName(key)).openInputStream()) {
				file = in.readAllBytes();
			}
			if (file.length == 0)
				return new Kept(0, new int[0][]);

			byte[] data;
			try (var in = new InflaterInputStream(new ByteArrayInputStream(file))) {
				data = in.readAllBytes();
			}
			if (data.length < HEADER_INTS * Integer.BYTES)
				return null;
			var ints = ByteBuffer.wrap(data).asIntBuffer();
			int period = ints.get();
			int frameCount = ints.get();
			if (frameCount < 1 || data.length != (HEADER_INTS + (long) frameCount * size) * Integer.BYTES)
				return null;

			int[][] frames = new int[frameCount][];
			for (int frame = 0; frame < frameCount; frame++) {
				frames[frame] = new int[size];
				ints.get(frames[frame]);
			}
			return new Kept(period, frames);
		} catch (NoSuchFileException ex) {
			return null;
		} catch (IOException ex) {
			log.debug("Unable to load item icon {}:", fileName(key), ex);
			return null;
		}
	}

	/**
	 * Keeps the icon's frames, or that it couldn't be rendered if there are none.
	 */
	void save(long key, int period, @Nullable int[][] frames) {
		try {
			byte[] file = new byte[0];
			if (frames != null) {
				var buffer = ByteBuffer.allocate((HEADER_INTS + frames.length * size) * Integer.BYTES);
				var ints = buffer.asIntBuffer();
				ints.put(period);
				ints.put(frames.length);
				for (int[] frame : frames)
					ints.put(frame);
				var out = new ByteArrayOutputStream();
				try (var deflater = new DeflaterOutputStream(out)) {
					deflater.write(buffer.array());
				}
				file = out.toByteArray();
			}

			// Moved into place, since other clients may be reading it
			folder.createDirectories();
			var temporary = folder.createTempFile(fileName(key), ".tmp");
			temporary.write(file);
			temporary.moveTo(folder.joinSegment(fileName(key)), REPLACE_EXISTING, ATOMIC_MOVE);
		} catch (IOException ex) {
			log.debug("Unable to keep item icon {}:", fileName(key), ex);
		}
	}

	void delete(long key) {
		try {
			folder.joinSegment(fileName(key)).deleteIfExists();
		} catch (IOException ex) {
			log.debug("Unable to delete item icon {}:", fileName(key), ex);
		}
	}

	/**
	 * Removes all but the most recently used folders, and the icons kept before there were folders.
	 */
	static void removeUnused(Filepath root) {
		if (!root.isDirectory())
			return;

		try {
			List<Filepath> entries;
			try (var list = root.walk(1)) {
				entries = list.filter(entry -> !entry.equals(root)).collect(Collectors.toList());
			}
			List<Filepath> folders = entries.stream()
				.filter(Filepath::isDirectory)
				.sorted(Comparator.comparing(ItemIconCache::lastModified).reversed())
				.collect(Collectors.toList());
			for (var unused : folders.subList(Math.min(MAX_FOLDERS, folders.size()), folders.size()))
				unused.deleteRecursively();
			for (var entry : entries)
				if (entry.isFile() && entry.getFileName().endsWith(".bin"))
					entry.delete();
		} catch (IOException ex) {
			log.debug("Unable to remove unused item icons:", ex);
		}
	}

	private static FileTime lastModified(Filepath folder) {
		try {
			return folder.getLastModifiedTime();
		} catch (IOException ex) {
			return FileTime.fromMillis(0);
		}
	}

	private static String fileName(long key) {
		return String.format("%016x", key);
	}
}

package io.mark.hditemicons.hd;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import net.runelite.api.Model;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;

import static io.mark.hditemicons.hd.IconMath.ceilToInt;
import static io.mark.hditemicons.hd.IconMath.clampInt;
import static io.mark.hditemicons.hd.IconMath.decodeHsl;
import static io.mark.hditemicons.hd.IconMath.floorToInt;
import static io.mark.hditemicons.hd.IconMath.wrap;

class ItemIconRasterizer {
	static final int ICON_WIDTH = 36;
	static final int ICON_HEIGHT = 32;

	static final int PROJECTION_SCALE = 512;
	private static final int PROJECTION_ORIGIN = 16;
	private static final int FIT_ITERATIONS = 10;
	private static final double FIT_TOLERANCE = 0.001;
	// Roughly what a 1.5x bilinear stretch costs in edge contrast
	private static final int SHARPEN_PERCENT = 50;
	private static final int MIN_THIN_LINE_COVERAGE = 48;
	private static final int[] NEIGHBOR_X = { -1, 1, 0, 0 };
	private static final int[] NEIGHBOR_Y = { 0, 0, -1, 1 };

	private static final int MAX_MISMATCHED_PIXELS = 3;
	private static final double MAX_MISMATCHED_FRACTION = 0.1;
	private static final int MAX_CHANNEL_ERROR = 32;

	static final class IconTexture {
		final int[] basePixels;
		final int direction, speed, size;

		IconTexture(int[] basePixels, int direction, int speed) {
			this.basePixels = basePixels;
			this.direction = direction;
			this.speed = speed;
			this.size = basePixels.length == 64 * 64 ? 64 : 128;
		}

		boolean scrolls() {
			return direction >= 1 && direction <= 4 && speed > 0 && basePixels.length == size * size;
		}

		int period() {
			return size / Math.min(Integer.lowestOneBit(speed), size);
		}
	}

	/**
	 * A snapshot of everything the rasterizer needs from a {@link Model}, copied up front so
	 * rendering can happen off the client thread.
	 */
	static final class IconModel {
		final float[] vertexX, vertexY, vertexZ;
		final int[] triangleA, triangleB, triangleC;
		final int[] shadeA, shadeB, shadeC;
		@Nullable final byte[] alpha;
		@Nullable final byte[] paintLayer;
		@Nullable final int[][] texelsByFace;
		@Nullable final int[] uvA, uvB, uvC;
		@Nullable final IconTexture[] textures;
		@Nullable final int[] textureByFace;
		final int animationPeriod;
		final boolean animated;

		private IconModel(float[] vertexX, float[] vertexY, float[] vertexZ,
						int[] triangleA, int[] triangleB, int[] triangleC,
						int[] shadeA, int[] shadeB, int[] shadeC,
						@Nullable byte[] alpha, @Nullable byte[] paintLayer,
						@Nullable int[][] texelsByFace, @Nullable int[] uvA, @Nullable int[] uvB, @Nullable int[] uvC,
						@Nullable IconTexture[] textures, @Nullable int[] textureByFace) {
			this.vertexX = vertexX;
			this.vertexY = vertexY;
			this.vertexZ = vertexZ;
			this.triangleA = triangleA;
			this.triangleB = triangleB;
			this.triangleC = triangleC;
			this.shadeA = shadeA;
			this.shadeB = shadeB;
			this.shadeC = shadeC;
			this.alpha = alpha;
			this.paintLayer = paintLayer;
			this.texelsByFace = texelsByFace;
			this.uvA = uvA;
			this.uvB = uvB;
			this.uvC = uvC;
			this.textures = textures;
			this.textureByFace = textureByFace;

			int animationPeriod = 0;
			if (textures != null)
				for (IconTexture texture : textures)
					if (texture.scrolls())
						animationPeriod = Math.max(animationPeriod, texture.period());
			this.animationPeriod = animationPeriod;
			this.animated = animationPeriod > 1;
		}

		/**
		 * Client thread only.
		 */
		@Nullable
		static IconModel capture(Model model, TextureProvider textures) {
			int faceCount = model.getFaceCount();
			int[][] texelsByFace = null;
			int[] uvA = null, uvB = null, uvC = null;
			IconTexture[] captured = null;
			int[] textureByFace = null;
			short[] faceTextures = model.getFaceTextures();
			if (faceTextures != null) {
				texelsByFace = new int[faceCount][];
				textureByFace = new int[faceCount];
				Arrays.fill(textureByFace, -1);
				uvA = Arrays.copyOf(model.getFaceIndices1(), faceCount);
				uvB = Arrays.copyOf(model.getFaceIndices2(), faceCount);
				uvC = Arrays.copyOf(model.getFaceIndices3(), faceCount);
				byte[] textureFaces = model.getTextureFaces();
				List<IconTexture> distinct = new ArrayList<>();
				Map<Integer, Integer> loadedTextures = new HashMap<>();
				for (int f = 0; f < faceCount; f++) {
					if (faceTextures[f] == -1)
						continue;
					int textureId = faceTextures[f];
					Integer index = loadedTextures.get(textureId);
					if (index == null) {
						int[] loaded = textures.load(textureId);
						if (loaded == null)
							return null;
						Texture texture = textureAt(textures, textureId);
						index = distinct.size();
						distinct.add(new IconTexture(loaded.clone(),
							texture == null ? 0 : texture.getAnimationDirection(),
							texture == null ? 0 : texture.getAnimationSpeed()));
						loadedTextures.put(textureId, index);
					}
					texelsByFace[f] = distinct.get(index).basePixels;
					textureByFace[f] = index;
					if (textureFaces != null && textureFaces[f] != -1) {
						int t = textureFaces[f] & 0xFF;
						uvA[f] = model.getTexIndices1()[t];
						uvB[f] = model.getTexIndices2()[t];
						uvC[f] = model.getTexIndices3()[t];
					}
				}
				captured = distinct.toArray(new IconTexture[0]);
			}

			int vertexCount = model.getVerticesCount();
			return new IconModel(
				Arrays.copyOf(model.getVerticesX(), vertexCount),
				Arrays.copyOf(model.getVerticesY(), vertexCount),
				Arrays.copyOf(model.getVerticesZ(), vertexCount),
				Arrays.copyOf(model.getFaceIndices1(), faceCount),
				Arrays.copyOf(model.getFaceIndices2(), faceCount),
				Arrays.copyOf(model.getFaceIndices3(), faceCount),
				Arrays.copyOf(model.getFaceColors1(), faceCount),
				Arrays.copyOf(model.getFaceColors2(), faceCount),
				Arrays.copyOf(model.getFaceColors3(), faceCount),
				model.getFaceTransparencies() == null ? null : Arrays.copyOf(model.getFaceTransparencies(), faceCount),
				model.getFaceRenderPriorities() == null ? null : Arrays.copyOf(model.getFaceRenderPriorities(), faceCount),
				texelsByFace, uvA, uvB, uvC, captured, textureByFace
			);
		}

		@Nullable
		private static Texture textureAt(TextureProvider provider, int textureId) {
			Texture[] all = provider.getTextures();
			return all != null && textureId >= 0 && textureId < all.length ? all[textureId] : null;
		}
	}

	private final IconModel model;
	private final int supersample;
	private final double[] posX, posY, posZ;
	private double centerOffsetX, centerOffsetY, cameraDistance;
	// The baseline every camera placement starts from, before any pan is layered on top.
	private final double naturalOffsetX, naturalOffsetY;

	@Nullable
	private int[][] texelsByFace;
	@Nullable
	private int[][] scrolledTexels;

	// Scratch buffers reused across the many renderSamples() calls a single fit performs
	// (up to FIT_ITERATIONS wide renders plus the final render), to avoid re-allocating
	// vertex-sized and face-sized arrays on every call.
	private final double[] camX, camY, camZ, screenX, screenY;
	private final long[] sortKeysScratch;
	private int[] samplesScratch;

	private static final int UNITY_RESIZE = 128;

	/**
	 * @param supersample how many samples per axis (so {@code supersample * supersample} samples
	 *                    per pixel) to render before downsampling - the plugin's configurable
	 *                    icon quality setting.
	 */
	ItemIconRasterizer(IconModel model, int pitchJau, int yawJau, int rollJau, int supersample) {
		this(model, pitchJau, yawJau, rollJau, UNITY_RESIZE, UNITY_RESIZE, UNITY_RESIZE, supersample);
	}

	/**
	 * @param resizeX128 per-axis model scale in the cache's resizeX/Y/Z units, 128 being 100%.
	 */
	ItemIconRasterizer(IconModel model, int pitchJau, int yawJau, int rollJau,
						double resizeX128, double resizeY128, double resizeZ128, int supersample) {
		this.model = model;
		this.supersample = supersample;
		this.texelsByFace = model.texelsByFace;
		int vertexCount = model.vertexX.length;
		posX = new double[vertexCount];
		posY = new double[vertexCount];
		posZ = new double[vertexCount];

		double roll = rollJau / IconMath.TURN * 2 * Math.PI;
		double yaw = yawJau / IconMath.TURN * 2 * Math.PI;
		double pitch = pitchJau / IconMath.TURN * 2 * Math.PI;
		double resizeX = resizeX128 / UNITY_RESIZE;
		double resizeY = resizeY128 / UNITY_RESIZE;
		double resizeZ = resizeZ128 / UNITY_RESIZE;

		// Resize applies in local space, before rotation, the same order the client uses
		for (int i = 0; i < vertexCount; i++) {
			double x = model.vertexX[i] * resizeX;
			double y = model.vertexY[i] * resizeY;
			double z = model.vertexZ[i] * resizeZ;

			double[] step1 = rotate(x, y, -roll);
			x = step1[0];
			y = step1[1];

			double[] step2 = rotate(x, z, -yaw);
			x = step2[0];
			z = step2[1];

			double[] step3 = rotate(y, z, pitch);
			y = step3[0];
			z = step3[1];

			posX[i] = x;
			posY[i] = y;
			posZ[i] = z;
		}

		double minX = Double.MAX_VALUE, minY = Double.MAX_VALUE, maxX = -Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
		for (int i = 0; i < vertexCount; i++) {
			minX = Math.min(minX, posX[i]);
			minY = Math.min(minY, posY[i]);
			maxX = Math.max(maxX, posX[i]);
			maxY = Math.max(maxY, posY[i]);
		}
		naturalOffsetX = -(minX + maxX) / 2;
		naturalOffsetY = -(minY + maxY) / 2;

		camX = new double[vertexCount];
		camY = new double[vertexCount];
		camZ = new double[vertexCount];
		screenX = new double[vertexCount];
		screenY = new double[vertexCount];
		sortKeysScratch = new long[model.triangleA.length];
	}

	private static double[] rotate(double u, double v, double angle) {
		double s = Math.sin(angle), c = Math.cos(angle);
		return new double[]{u * c - v * s, u * s + v * c};
	}

	/**
	 * Places the camera explicitly instead of fitting it to a reference icon. {@code offsetX}/
	 * {@code offsetY} are xOffset2d/yOffset2d-style nudges on top of the model's own centering,
	 * not the whole pan - the cache's values are only ever a few units off centre.
	 */
	void placeExplicitly(double cameraDistance, double offsetX, double offsetY) {
		this.cameraDistance = cameraDistance;
		this.centerOffsetX = naturalOffsetX + offsetX;
		this.centerOffsetY = naturalOffsetY + offsetY;
	}

	/**
	 * Solves for a camera distance and 2D offset whose rendered silhouette matches
	 * {@code reference} (the game's own border-less icon pixels for the same item), then
	 * confirms the match is close enough to trust. Returns false if no plausible fit is found.
	 */
	boolean fitToReferenceSilhouette(int[] reference, int[] palette) {
		double[] targetCoverage = new double[reference.length];
		for (int i = 0; i < reference.length; i++)
			targetCoverage[i] = reference[i] == 0 ? 0 : 1;
		Silhouette target = measureSilhouette(targetCoverage, ICON_WIDTH, 0, 0);
		if (target.coverage == 0)
			return false;

		double maxRadius = 0;
		for (int i = 0; i < posX.length; i++)
			maxRadius = Math.max(maxRadius, Math.sqrt(posX[i] * posX[i] + posY[i] * posY[i] + posZ[i] * posZ[i]));

		// Fitted by spread (the silhouette's radius of gyration) rather than raw area, since
		// thin shapes render thicker in the game's icons than their true silhouette area implies.
		cameraDistance = maxRadius + PROJECTION_SCALE * maxRadius / Math.sqrt(target.coverage / Math.PI);
		centerOffsetX = naturalOffsetX;
		centerOffsetY = naturalOffsetY;

		for (int pass = 0; pass < FIT_ITERATIONS; pass++) {
			int[] wide = renderSamples(cameraDistance, 1, 1, -ICON_WIDTH, -ICON_HEIGHT, ICON_WIDTH * 3, ICON_HEIGHT * 3, palette);
			double[] wideCoverage = new double[wide.length];
			for (int i = 0; i < wide.length; i++)
				wideCoverage[i] = (wide[i] >>> 24) / 255.0;
			Silhouette current = measureSilhouette(wideCoverage, ICON_WIDTH * 3, -ICON_WIDTH, -ICON_HEIGHT);
			if (current.coverage == 0)
				return false;

			double scale = current.spread / target.spread;
			cameraDistance *= scale;
			centerOffsetX += (target.centerX - current.centerX) * cameraDistance / PROJECTION_SCALE;
			centerOffsetY += (target.centerY - current.centerY) * cameraDistance / PROJECTION_SCALE;
			if (cameraDistance <= maxRadius)
				return false;

			boolean converged = Math.abs(scale - 1) < FIT_TOLERANCE
				&& Math.abs(target.centerX - current.centerX) < FIT_TOLERANCE * 10
				&& Math.abs(target.centerY - current.centerY) < FIT_TOLERANCE * 10;
			if (converged)
				break;
		}

		int[] fitted = renderSamples(cameraDistance, 1, 1, 0, 0, ICON_WIDTH, ICON_HEIGHT, palette);
		return verifiesAgainst(fitted, reference, target.coverage);
	}

	private static final class Silhouette {
		final double coverage, centerX, centerY, spread;

		Silhouette(double coverage, double centerX, double centerY, double spread) {
			this.coverage = coverage;
			this.centerX = centerX;
			this.centerY = centerY;
			this.spread = spread;
		}
	}

	private static Silhouette measureSilhouette(double[] coverage, int width, int left, int top) {
		double area = 0, momentX = 0, momentY = 0, momentR2 = 0;
		for (int i = 0; i < coverage.length; i++) {
			double px = i % width + left + 0.5;
			double py = i / width + top + 0.5;
			area += coverage[i];
			momentX += coverage[i] * px;
			momentY += coverage[i] * py;
			momentR2 += coverage[i] * (px * px + py * py);
		}
		if (area == 0)
			return new Silhouette(0, 0, 0, 0);
		double centerX = momentX / area;
		double centerY = momentY / area;
		double variance = Math.max(0, momentR2 / area - centerX * centerX - centerY * centerY);
		return new Silhouette(area, centerX, centerY, Math.sqrt(variance));
	}

	/**
	 * Confirms a solved camera placement is actually a good match: few disagreeing pixels
	 * (allowing for antialiasing noise near edges) and similar average colour.
	 */
	private boolean verifiesAgainst(int[] fitted, int[] reference, double referenceCoverage) {
		boolean[] weDrew = new boolean[fitted.length];
		boolean[] weDrewFaintly = new boolean[fitted.length];
		boolean[] theyDrew = new boolean[fitted.length];
		for (int i = 0; i < fitted.length; i++) {
			weDrew[i] = fitted[i] >>> 24 >= 128;
			weDrewFaintly[i] = fitted[i] >>> 24 > 0;
			theyDrew[i] = reference[i] != 0;
		}

		int disagreements = 0;
		double ourCoverage = 0;
		double[] ourColor = new double[3];
		double[] theirColor = new double[3];
		for (int i = 0; i < fitted.length; i++) {
			if (theyDrew[i] && !hasNearbyMark(weDrewFaintly, i) || weDrew[i] && !hasNearbyMark(theyDrew, i))
				disagreements++;
			ourCoverage += (fitted[i] >>> 24) / 255.0;
			for (int c = 0; c < 3; c++) {
				ourColor[c] += fitted[i] >> c * 8 & 0xFF;
				if (theyDrew[i])
					theirColor[c] += reference[i] >> c * 8 & 0xFF;
			}
		}

		if (disagreements > Math.max(MAX_MISMATCHED_PIXELS, MAX_MISMATCHED_FRACTION * referenceCoverage))
			return false;
		for (int c = 0; c < 3; c++)
			if (Math.abs(ourColor[c] / ourCoverage - theirColor[c] / referenceCoverage) > MAX_CHANNEL_ERROR)
				return false;
		return true;
	}

	private static boolean hasNearbyMark(boolean[] mask, int index) {
		int x = index % ICON_WIDTH;
		int y = index / ICON_WIDTH;
		for (int ny = Math.max(0, y - 2); ny <= Math.min(ICON_HEIGHT - 1, y + 2); ny++)
			for (int nx = Math.max(0, x - 2); nx <= Math.min(ICON_WIDTH - 1, x + 2); nx++)
				if (mask[ny * ICON_WIDTH + nx])
					return true;
		return false;
	}

	void animateTo(int cycles) {
		IconTexture[] textures = model.textures;
		if (!model.animated || textures == null || model.textureByFace == null)
			return;

		if (scrolledTexels == null) {
			scrolledTexels = new int[textures.length][];
			for (int t = 0; t < textures.length; t++)
				scrolledTexels[t] = textures[t].scrolls()
					? new int[textures[t].basePixels.length] : textures[t].basePixels;
			int[][] byFace = new int[model.textureByFace.length][];
			for (int f = 0; f < byFace.length; f++) {
				int texture = model.textureByFace[f];
				byFace[f] = texture == -1 ? null : scrolledTexels[texture];
			}
			texelsByFace = byFace;
		}

		for (int t = 0; t < textures.length; t++)
			if (textures[t].scrolls())
				scroll(textures[t], scrolledTexels[t], cycles);
	}

	static void scroll(IconTexture texture, int[] into, int cycles) {
		int[] base = texture.basePixels;
		int size = texture.size;
		int phase = (int) (((long) cycles * texture.speed) % size);
		if (texture.direction == 1 || texture.direction == 3)
			phase = -phase;

		if (texture.direction <= 2) {
			int shift = phase * size;
			int mask = base.length - 1;
			for (int i = 0; i < base.length; i++)
				into[i] = base[shift + i & mask];
		} else {
			int mask = size - 1;
			for (int row = 0; row < base.length; row += size)
				for (int x = 0; x < size; x++)
					into[row + x] = base[row + (phase + x & mask)];
		}
	}

	/**
	 * Renders the fitted camera placement into a border-margin-sized icon buffer.
	 */
	int[] render(int marginPixels, boolean outlined, boolean sharpen, int[] palette) {
		int width = ICON_WIDTH + 2 * marginPixels;
		int height = ICON_HEIGHT + 2 * marginPixels;
		int[] pixels = renderSamples(cameraDistance, 1, 1, -marginPixels, -marginPixels, width, height, palette);
		int[] shaded = sharpen ? sharpen(pixels, width, height) : pixels;
		// Outlined off the unsharpened pixels: sharpening nudges alpha across the threshold
		// filled() tests, which would otherwise reshape the ring depending on the setting
		return outlined ? outline(pixels, shaded, width, height) : shaded;
	}

	/**
	 * Pre-compensates for the interface being stretched: the icon is about to be scaled up and
	 * blurred by a filter we don't control, so it's sharpened by roughly what that will cost. Only
	 * worth doing when the icon really is stretched - at 1:1 it would just look over-sharpened.
	 */
	private static int[] sharpen(int[] pixels, int width, int height) {
		int[] sharpened = new int[pixels.length];
		for (int y = 0; y < height; y++) {
			for (int x = 0; x < width; x++) {
				int neighbours = 0, blurA = 0, blurR = 0, blurG = 0, blurB = 0;
				for (int n = 0; n < NEIGHBOR_X.length; n++) {
					int nx = x + NEIGHBOR_X[n], ny = y + NEIGHBOR_Y[n];
					if (nx < 0 || nx >= width || ny < 0 || ny >= height)
						continue;
					int neighbour = pixels[ny * width + nx];
					blurA += neighbour >>> 24;
					blurR += neighbour >> 16 & 0xFF;
					blurG += neighbour >> 8 & 0xFF;
					blurB += neighbour & 0xFF;
					neighbours++;
				}

				int i = y * width + x;
				int pixel = pixels[i];
				if (neighbours == 0) {
					sharpened[i] = pixel;
					continue;
				}

				int alpha = unsharp(pixel >>> 24, blurA / neighbours, 255);
				// Colour is premultiplied, so a channel above its own alpha would composite as a
				// bright fringe rather than a brighter pixel
				sharpened[i] = alpha << 24
					| unsharp(pixel >> 16 & 0xFF, blurR / neighbours, alpha) << 16
					| unsharp(pixel >> 8 & 0xFF, blurG / neighbours, alpha) << 8
					| unsharp(pixel & 0xFF, blurB / neighbours, alpha);
			}
		}
		return sharpened;
	}

	private static int unsharp(int value, int blurred, int max) {
		return clampInt(value + (value - blurred) * SHARPEN_PERCENT / 100, 0, max);
	}

	/**
	 * Outlines the icon the way the game does, with a solid black ring a whole pixel wide around the pixels
	 * the model mostly covers. A smoothed outline would smear into a dark halo once the interface is stretched.
	 */
	private static int[] outline(int[] shape, int[] pixels, int width, int height) {
		boolean[] filled = filled(shape);
		boolean[] thin = thinLines(shape, filled, width, height);
		for (int i = 0; i < filled.length; i++)
			filled[i] |= thin[i];
		removeSpurs(filled, width, height);
		boolean[] ring = ring(filled, width, height);
		int[] outlined = new int[pixels.length];
		for (int i = 0; i < pixels.length; i++) {
			if (filled[i] && thin[i])
				outlined[i] = opaque(pixels[i], shape[i] >>> 24);
			else if (filled[i])
				outlined[i] = over(pixels[i], 0xFF000000);
			else if (ring[i])
				outlined[i] = 0xFF000000;
		}
		return outlined;
	}

	/**
	 * Parts thinner than a pixel, like a crossbow's string, cover less than half of every pixel they cross, so they'd
	 * be left out. They're kept a whole pixel wide: where they cover the most of their row or column, unlike the edge
	 * of something wider, which only gets more covered further in.
	 */
	private static boolean[] thinLines(int[] shape, boolean[] filled, int width, int height) {
		boolean[] thin = new boolean[shape.length];
		for (int y = 0; y < height; y++) {
			for (int x = 0; x < width; x++) {
				int i = y * width + x;
				int coverage = shape[i] >>> 24;
				if (filled[i] || coverage < MIN_THIN_LINE_COVERAGE)
					continue;
				int left = x > 0 ? shape[i - 1] >>> 24 : 0;
				int right = x < width - 1 ? shape[i + 1] >>> 24 : 0;
				int up = y > 0 ? shape[i - width] >>> 24 : 0;
				int down = y < height - 1 ? shape[i + width] >>> 24 : 0;
				// Ties go to the first of the two, so a line split evenly over two pixels stays one wide
				thin[i] = coverage > left && coverage >= right || coverage > up && coverage >= down;
			}
		}
		return thin;
	}

	// Premultiplied colour with its coverage, as the colour it would have if it covered the whole pixel
	private static int opaque(int pixel, int coverage) {
		int result = 0xFF000000;
		for (int shift = 0; shift < 24; shift += 8)
			result |= Math.min(255, (pixel >>> shift & 0xFF) * 255 / coverage) << shift;
		return result;
	}

	/**
	 * Removes single pixels sticking out of an edge: ones touching the icon on one side only, where it's
	 * wider than them. The ends of thin lines stay.
	 */
	private static void removeSpurs(boolean[] filled, int width, int height) {
		boolean[] spurs = new boolean[filled.length];
		int[] steps = { -1, 1, -width, width };
		for (int y = 1; y < height - 1; y++) {
			for (int x = 1; x < width - 1; x++) {
				int i = y * width + x;
				if (!filled[i])
					continue;
				int touching = 0, towards = 0, across = 0;
				for (int step : steps) {
					if (filled[i + step]) {
						touching++;
						towards = step;
						across = step == -1 || step == 1 ? width : 1;
					}
				}
				spurs[i] = touching == 1 && filled[i + towards - across] && filled[i + towards + across];
			}
		}
		for (int i = 0; i < filled.length; i++)
			if (spurs[i])
				filled[i] = false;
	}

	/**
	 * The icon with the white border the game draws around selected items.
	 */
	static int[] withSelectionBorder(int[] pixels, int width, int height) {
		boolean[] ring = outlineRing(pixels, width, height);
		int[] selected = pixels.clone();
		for (int i = 0; i < pixels.length; i++)
			if (ring[i])
				selected[i] = 0xFFFFFFFF;
		return selected;
	}

	/**
	 * The pixels right outside the icon, where the game draws outlines.
	 */
	static boolean[] outlineRing(int[] pixels, int width, int height) {
		return ring(filled(pixels), width, height);
	}

	private static boolean[] filled(int[] pixels) {
		boolean[] filled = new boolean[pixels.length];
		for (int i = 0; i < pixels.length; i++)
			filled[i] = pixels[i] >>> 24 >= 128;
		return filled;
	}

	private static boolean[] ring(boolean[] filled, int width, int height) {
		boolean[] ring = new boolean[filled.length];
		for (int y = 0; y < height; y++) {
			for (int x = 0; x < width; x++) {
				int i = y * width + x;
				ring[i] = !filled[i] && (x > 0 && filled[i - 1] || x < width - 1 && filled[i + 1]
					|| y > 0 && filled[i - width] || y < height - 1 && filled[i + width]);
			}
		}
		return ring;
	}

	/**
	 * Alpha-composites {@code top} over {@code bottom}, both straight (non-premultiplied) ARGB.
	 */
	static int[] compositeOver(int[] top, int[] bottom) {
		int[] result = new int[top.length];
		for (int i = 0; i < top.length; i++)
			result[i] = over(top[i], bottom[i]);
		return result;
	}

	private static int over(int top, int bottom) {
		int remaining = 255 - (top >>> 24);
		int result = 0;
		for (int shift = 0; shift < 32; shift += 8) {
			int blended = (top >>> shift & 0xFF) + ((bottom >>> shift & 0xFF) * remaining + 127) / 255;
			result |= Math.min(255, blended) << shift;
		}
		return result;
	}

	private int[] renderSamples(double distance, double scaleX, double scaleY, double left, double top,
								int width, int height, int[] palette) {
		int vertexCount = posX.length;
		for (int i = 0; i < vertexCount; i++) {
			camX[i] = posX[i] + centerOffsetX;
			camY[i] = posY[i] + centerOffsetY;
			camZ[i] = posZ[i] + distance;
			screenX[i] = (PROJECTION_ORIGIN + PROJECTION_SCALE * camX[i] / camZ[i] - left) * scaleX * supersample;
			screenY[i] = (PROJECTION_ORIGIN + PROJECTION_SCALE * camY[i] / camZ[i] - top) * scaleY * supersample;
		}
		double rayScaleX = 1 / (scaleX * supersample), rayOffsetX = left - PROJECTION_ORIGIN;
		double rayScaleY = 1 / (scaleY * supersample), rayOffsetY = top - PROJECTION_ORIGIN;

		int samplesWide = width * supersample;
		int samplesHigh = height * supersample;
		int[] samples = obtainSamplesBuffer(samplesWide * samplesHigh);
		for (int face : paintOrder(screenX, screenY, camZ))
			paintFace(face, screenX, screenY, camX, camY, camZ, rayScaleX, rayOffsetX, rayScaleY, rayOffsetY,
				samplesWide, samplesHigh, palette, samples);

		return downsample(samples, samplesWide, width, height);
	}

	private int[] obtainSamplesBuffer(int size) {
		if (samplesScratch == null || samplesScratch.length != size)
			samplesScratch = new int[size];
		else
			Arrays.fill(samplesScratch, 0);
		return samplesScratch;
	}

	private int[] downsample(int[] samples, int samplesWide, int width, int height) {
		int[] pixels = new int[width * height];
		int samplesPerPixel = supersample * supersample;
		int rounding = samplesPerPixel / 2;
		for (int py = 0; py < height; py++) {
			for (int px = 0; px < width; px++) {
				int covered = 0, r = 0, g = 0, b = 0;
				for (int sy = 0; sy < supersample; sy++) {
					int rowStart = (py * supersample + sy) * samplesWide + px * supersample;
					for (int sx = 0; sx < supersample; sx++) {
						int rgb = samples[rowStart + sx];
						if (rgb != 0) {
							covered++;
							r += rgb >> 16 & 0xFF;
							g += rgb >> 8 & 0xFF;
							b += rgb & 0xFF;
						}
					}
				}
				pixels[py * width + px] =
					(covered * 255 + rounding) / samplesPerPixel << 24 |
					(r + rounding) / samplesPerPixel << 16 |
					(g + rounding) / samplesPerPixel << 8 |
					(b + rounding) / samplesPerPixel;
			}
		}
		return pixels;
	}

	/**
	 * Back-to-front face draw order (painter's algorithm), with faces that have an explicit
	 * render priority (0-11) grouped and interleaved the way the game does: priorities 0-9 in
	 * strict priority order, with priorities 10 and 11 slotted in among them by depth.
	 */
	private int[] paintOrder(double[] screenX, double[] screenY, double[] depth) {
		int faceCount = model.triangleA.length;
		long[] sortKeys = sortKeysScratch;
		int visibleCount = 0;
		for (int f = 0; f < faceCount; f++) {
			if (model.shadeC[f] == -2)
				continue; // hidden face
			int a = model.triangleA[f], b = model.triangleB[f], c = model.triangleC[f];
			if (isBackFacing(screenX, screenY, a, b, c))
				continue;
			int faceDepth = floorToInt((depth[a] + depth[b] + depth[c]) / 3);
			// Pack so sorting by the key sorts by depth (descending) with the face index as a
			// tie-breaker, without boxing into Integer[].
			sortKeys[visibleCount] = ((long) -faceDepth << 32) | (f & 0xFFFFFFFFL);
			visibleCount++;
		}
		Arrays.sort(sortKeys, 0, visibleCount);
		int[] depthOrder = new int[visibleCount];
		int[] depthOrderDepth = new int[visibleCount];
		for (int i = 0; i < visibleCount; i++) {
			depthOrder[i] = (int) sortKeys[i];
			depthOrderDepth[i] = (int) -(sortKeys[i] >> 32);
		}

		if (model.paintLayer == null)
			return depthOrder;
		return interleaveByPriority(depthOrder, depthOrderDepth);
	}

	private static boolean isBackFacing(double[] screenX, double[] screenY, int a, int b, int c) {
		return (screenX[a] - screenX[b]) * (screenY[c] - screenY[b]) <= (screenX[c] - screenX[b]) * (screenY[a] - screenY[b]);
	}

	/**
	 * {@code depthOrder}/{@code depthOrderDepth} are aligned by index (already sorted
	 * back-to-front); this groups them by the model's explicit render priority instead.
	 */
	private int[] interleaveByPriority(int[] depthOrder, int[] depthOrderDepth) {
		double[] depthTotal = new double[12];
		int[] countByPriority = new int[12];
		for (int i = 0; i < depthOrder.length; i++) {
			int priority = model.paintLayer[depthOrder[i]];
			depthTotal[priority] += depthOrderDepth[i];
			countByPriority[priority]++;
		}
		double[] slotDepth = new double[10];
		Arrays.fill(slotDepth, Double.MAX_VALUE);
		slotDepth[0] = averageDepth(depthTotal, countByPriority, 1, 2);
		slotDepth[3] = averageDepth(depthTotal, countByPriority, 3, 4);
		slotDepth[5] = averageDepth(depthTotal, countByPriority, 6, 8);

		int[] deferredFace = new int[countByPriority[10] + countByPriority[11]];
		int[] deferredDepth = new int[deferredFace.length];
		int deferredCount = 0;
		for (int priority = 10; priority <= 11; priority++) {
			for (int i = 0; i < depthOrder.length; i++) {
				if (model.paintLayer[depthOrder[i]] == priority) {
					deferredFace[deferredCount] = depthOrder[i];
					deferredDepth[deferredCount] = depthOrderDepth[i];
					deferredCount++;
				}
			}
		}

		int[] order = new int[depthOrder.length];
		int next = 0, nextDeferred = 0;
		for (int priority = 0; priority < 10; priority++) {
			while (nextDeferred < deferredCount && deferredDepth[nextDeferred] > slotDepth[priority])
				order[next++] = deferredFace[nextDeferred++];
			for (int i = 0; i < depthOrder.length; i++)
				if (model.paintLayer[depthOrder[i]] == priority)
					order[next++] = depthOrder[i];
		}
		while (nextDeferred < deferredCount)
			order[next++] = deferredFace[nextDeferred++];
		return order;
	}

	private static double averageDepth(double[] depthTotal, int[] count, int priorityA, int priorityB) {
		int n = count[priorityA] + count[priorityB];
		return n == 0 ? 0 : (depthTotal[priorityA] + depthTotal[priorityB]) / n;
	}

	private void paintFace(int face, double[] screenX, double[] screenY, double[] camX, double[] camY, double[] camZ,
							double rayScaleX, double rayOffsetX, double rayScaleY, double rayOffsetY,
							int width, int height, int[] palette, int[] samples) {
		int a = model.triangleA[face], b = model.triangleB[face], c = model.triangleC[face];
		double xa = screenX[a], ya = screenY[a];
		double xb = screenX[b], yb = screenY[b];
		double xc = screenX[c], yc = screenY[c];
		double area = (xb - xa) * (yc - ya) - (xc - xa) * (yb - ya);
		if (area == 0)
			return;
		double inverseArea = 1 / area;

		int minX = clampInt(ceilToInt(Math.min(xa, Math.min(xb, xc)) - 0.5), 0, width - 1);
		int maxX = clampInt(floorToInt(Math.max(xa, Math.max(xb, xc)) - 0.5), 0, width - 1);
		int minY = clampInt(ceilToInt(Math.min(ya, Math.min(yb, yc)) - 0.5), 0, height - 1);
		int maxY = clampInt(floorToInt(Math.max(ya, Math.max(yb, yc)) - 0.5), 0, height - 1);

		boolean flatShaded = model.shadeC[face] == -1;
		int shadeA = model.shadeA[face], shadeB = model.shadeB[face], shadeC = model.shadeC[face];
		if (flatShaded)
			shadeB = shadeC = shadeA;
		int transparency = model.alpha == null ? 0 : model.alpha[face] & 0xFF;

		int[] texels = texelsByFace == null ? null : texelsByFace[face];
		int textureSize = 0;
		double[] planeU = null, planeV = null, planeW = null;
		if (texels != null) {
			textureSize = (int) Math.sqrt(texels.length);
			double[] origin = corner(camX, camY, camZ, model.uvA[face]);
			double[] edgeM = subtract(corner(camX, camY, camZ, model.uvB[face]), origin);
			double[] edgeN = subtract(corner(camX, camY, camZ, model.uvC[face]), origin);
			planeU = cross(edgeN, origin);
			planeV = cross(origin, edgeM);
			planeW = cross(edgeM, edgeN);
		}

		for (int sy = minY; sy <= maxY; sy++) {
			double py = sy + 0.5;
			for (int sx = minX; sx <= maxX; sx++) {
				double px = sx + 0.5;
				double wa = ((xb - px) * (yc - py) - (xc - px) * (yb - py)) * inverseArea;
				double wb = ((xc - px) * (ya - py) - (xa - px) * (yc - py)) * inverseArea;
				double wc = 1 - wa - wb;
				if (wa < 0 || wb < 0 || wc < 0)
					continue;

				int color;
				if (texels == null) {
					int shade = clampInt(floorToInt(wa * shadeA + wb * shadeB + wc * shadeC), 0, 0xFFFF);
					color = palette[flatShaded ? shadeA : shade];
				} else {
					double rayX = px * rayScaleX + rayOffsetX;
					double rayY = py * rayScaleY + rayOffsetY;
					double along = rayX * planeW[0] + rayY * planeW[1] + PROJECTION_SCALE * planeW[2];
					double u = (rayX * planeU[0] + rayY * planeU[1] + PROJECTION_SCALE * planeU[2]) / along;
					double v = (rayX * planeV[0] + rayY * planeV[1] + PROJECTION_SCALE * planeV[2]) / along;
					int texel = texels[
						wrap(floorToInt(v * textureSize), textureSize) * textureSize +
							clampInt(floorToInt(u * textureSize), 0, textureSize - 1)];
					if (texel == 0)
						continue;
					int shade = (int) ((wa * shadeA + wb * shadeB + wc * shadeC) * 2);
					color = Math.max(1, applyShade(texel, shade));
				}

				int i = sy * width + sx;
				samples[i] = transparency == 0 ? color : blend(color, samples[i], transparency);
			}
		}
	}

	private static double[] corner(double[] camX, double[] camY, double[] camZ, int i) {
		return new double[]{camX[i], camY[i], camZ[i]};
	}

	private static double[] subtract(double[] a, double[] b) {
		return new double[]{a[0] - b[0], a[1] - b[1], a[2] - b[2]};
	}

	private static double[] cross(double[] a, double[] b) {
		return new double[]{a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]};
	}

	private static int applyShade(int rgb, int shade) {
		return ((rgb & 0xFF00FF) * shade >> 8 & 0xFF00FF) + ((rgb & 0xFF00) * shade >> 8 & 0xFF00);
	}

	private static int blend(int color, int behind, int transparency) {
		int opacity = 256 - transparency;
		return ((color & 0xFF00FF) * opacity + (behind & 0xFF00FF) * transparency >> 8 & 0xFF00FF)
			+ ((color & 0xFF00) * opacity + (behind & 0xFF00) * transparency >> 8 & 0xFF00);
	}

	/**
	 * Precomputes an RGB lookup for every possible packed-HSL value, gamma-corrected by
	 * {@code brightness} the same way the game darkens its item icon colours (rounding to
	 * 8-bit precision before the gamma curve is applied, matching the game's own precision).
	 */
	static int[] buildPalette(double brightness) {
		int[] palette = new int[0x10000];
		for (int packed = 0; packed < palette.length; packed++) {
			double[] srgb = decodeHsl(packed);
			int rgb = 0;
			for (double channel : srgb) {
				double rounded = ((int) (channel * 256)) / 256.0;
				int component = clampInt((int) (Math.pow(rounded, brightness) * 256), 0, 255);
				rgb = rgb << 8 | component;
			}
			palette[packed] = Math.max(1, rgb); // 0 means nothing was drawn
		}
		return palette;
	}
}

package io.mark.hditemicons.hd;

import io.mark.hditemicons.CustomRotation;
import io.mark.hditemicons.CustomRotationStorage;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.Image;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.IntConsumer;
import java.util.function.IntSupplier;
import javax.annotation.Nullable;
import javax.swing.ButtonGroup;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JRadioButton;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.WindowConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.event.ChangeListener;
import net.runelite.client.util.ImageUtil;

import static io.mark.hditemicons.hd.ItemIconRasterizer.ICON_HEIGHT;
import static io.mark.hditemicons.hd.ItemIconRasterizer.ICON_WIDTH;

/**
 * A live property panel for an item's icon camera placement. Every change applies and saves
 * immediately, so there's no Save step - only per-field resets and a reset-everything.
 */
final class RotationEditorDialog extends JFrame {
	private enum Mode { ROTATE, PAN, SCALE }

	/**
	 * One entry of the saved-icon dropdown, whose values can be copied onto the item being
	 * edited. The prompt entry carries no rotation.
	 */
	static final class Preset {
		private final String label;
		@Nullable
		private final CustomRotation rotation;

		Preset(String label, @Nullable CustomRotation rotation) {
			this.label = label;
			this.rotation = rotation;
		}

		@Override
		public String toString() {
			return label;
		}
	}

	private static final ImageIcon RESET_ICON =
		new ImageIcon(ImageUtil.loadImageResource(RotationEditorDialog.class, "reset.png"));

	private static final int PREVIEW_SCALE = 6;
	private static final int COMMIT_THROTTLE_MS = 100;
	private static final double ANGLE_PER_DRAG_PIXEL = 4;
	private static final double RESIZE_PER_DRAG_PIXEL = 1;
	private static final double ZOOM_PER_WHEEL_NOTCH = 50;
	private static final int SPINNER_BOUND = 200_000;

	private final int itemId;
	private final ItemIconRasterizer.IconModel model;
	@Nullable
	private final int[] referencePixels;
	private final int[] palette;
	private final int supersample;
	private final CustomRotationStorage rotationStorage;
	private final IntConsumer onChanged;
	private final CustomRotation defaults;

	private final ExecutorService previewExecutor = Executors.newSingleThreadExecutor(runnable -> {
		Thread thread = new Thread(runnable, "hd-item-icon-rotation-preview");
		thread.setDaemon(true);
		return thread;
	});
	private final Timer commitThrottle;
	private long previewGeneration;

	private Mode mode = Mode.ROTATE;
	private int dragX, dragY;

	private final JSpinner zoomSpinner;
	private final JSpinner panXSpinner;
	private final JSpinner panYSpinner;
	private final JSpinner angleXSpinner;
	private final JSpinner angleYSpinner;
	private final JSpinner angleZSpinner;
	private final JSpinner resizeXSpinner;
	private final JSpinner resizeYSpinner;
	private final JSpinner resizeZSpinner;
	private final JLabel previewLabel;
	private final JLabel hintLabel;

	RotationEditorDialog(String itemName, int itemId, CustomRotation initial, CustomRotation defaults,
						List<Preset> presets, ItemIconRasterizer.IconModel model, @Nullable int[] referencePixels,
						int[] palette, int supersample,
						CustomRotationStorage rotationStorage, IntConsumer onChanged) {
		super("Edit icon");
		this.itemId = itemId;
		this.model = model;
		this.referencePixels = referencePixels;
		this.palette = palette;
		this.supersample = supersample;
		this.rotationStorage = rotationStorage;
		this.onChanged = onChanged;
		this.defaults = defaults;

		setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
		setResizable(false);
		setAlwaysOnTop(true);

		JLabel subtitle = new JLabel(itemName + " (" + itemId + ")", SwingConstants.CENTER);

		previewLabel = new JLabel();
		previewLabel.setHorizontalAlignment(SwingConstants.CENTER);
		previewLabel.setOpaque(true);
		previewLabel.setBackground(Color.DARK_GRAY);
		previewLabel.setPreferredSize(new Dimension(ICON_WIDTH * PREVIEW_SCALE, ICON_HEIGHT * PREVIEW_SCALE));

		JRadioButton rotateButton = new JRadioButton("Rotate", true);
		JRadioButton panButton = new JRadioButton("Pan");
		JRadioButton scaleButton = new JRadioButton("Scale");
		ButtonGroup modeGroup = new ButtonGroup();
		modeGroup.add(rotateButton);
		modeGroup.add(panButton);
		modeGroup.add(scaleButton);
		rotateButton.addActionListener(e -> setMode(Mode.ROTATE));
		panButton.addActionListener(e -> setMode(Mode.PAN));
		scaleButton.addActionListener(e -> setMode(Mode.SCALE));
		JPanel modePanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 12, 0));
		modePanel.add(rotateButton);
		modePanel.add(panButton);
		modePanel.add(scaleButton);

		hintLabel = new JLabel("", SwingConstants.CENTER);
		hintLabel.setFont(hintLabel.getFont().deriveFont(hintLabel.getFont().getSize2D() - 1f));
		updateHint();

		zoomSpinner = newSpinner(initial.zoom2d);
		panXSpinner = newSpinner(initial.offsetX);
		panYSpinner = newSpinner(initial.offsetY);
		angleXSpinner = newSpinner(initial.xan2d);
		angleYSpinner = newSpinner(initial.yan2d);
		angleZSpinner = newSpinner(initial.zan2d);
		resizeXSpinner = newSpinner(initial.resizeX);
		resizeYSpinner = newSpinner(initial.resizeY);
		resizeZSpinner = newSpinner(initial.resizeZ);

		// A throttle, not a debounce, so the live icon keeps pace with a drag instead of
		// freezing until it ends. The preview isn't gated by it at all.
		commitThrottle = new Timer(COMMIT_THROTTLE_MS, e -> commit());
		commitThrottle.setRepeats(false);
		ChangeListener changed = e -> onValueChanged();
		for (JSpinner spinner : new JSpinner[]{zoomSpinner, panXSpinner, panYSpinner,
			angleXSpinner, angleYSpinner, angleZSpinner, resizeXSpinner, resizeYSpinner, resizeZSpinner})
			spinner.addChangeListener(changed);

		attachDragControls();

		JPanel fields = new JPanel(new GridLayout(9, 1, 0, 4));
		fields.add(fieldRow("Zoom", zoomSpinner, () -> defaults.zoom2d));
		fields.add(fieldRow("Pan X", panXSpinner, () -> defaults.offsetX));
		fields.add(fieldRow("Pan Y", panYSpinner, () -> defaults.offsetY));
		fields.add(fieldRow("Angle X", angleXSpinner, () -> defaults.xan2d));
		fields.add(fieldRow("Angle Y", angleYSpinner, () -> defaults.yan2d));
		fields.add(fieldRow("Angle Z", angleZSpinner, () -> defaults.zan2d));
		fields.add(fieldRow("Resize X", resizeXSpinner, () -> defaults.resizeX));
		fields.add(fieldRow("Resize Y", resizeYSpinner, () -> defaults.resizeY));
		fields.add(fieldRow("Resize Z", resizeZSpinner, () -> defaults.resizeZ));

		Preset prompt = new Preset(presets.isEmpty() ? "No other saved icons" : "Pick a saved icon...", null);
		JComboBox<Preset> presetBox = new JComboBox<>();
		presetBox.addItem(prompt);
		for (Preset preset : presets)
			presetBox.addItem(preset);
		presetBox.setEnabled(!presets.isEmpty());
		presetBox.addActionListener(e -> {
			Preset picked = (Preset) presetBox.getSelectedItem();
			if (picked == null || picked.rotation == null)
				return;
			applyImmediately(() -> applyToSpinners(picked.rotation));
			// Back to the prompt, since this copies values rather than staying set to one
			presetBox.setSelectedItem(prompt);
		});

		JPanel presetRow = new JPanel(new BorderLayout(4, 0));
		JLabel presetLabel = new JLabel("Copy from");
		presetLabel.setPreferredSize(new Dimension(60, presetLabel.getPreferredSize().height));
		presetRow.add(presetLabel, BorderLayout.WEST);
		presetRow.add(presetBox, BorderLayout.CENTER);

		JButton resetAll = new JButton("Reset to default");
		resetAll.addActionListener(e -> applyImmediately(() -> applyToSpinners(defaults)));

		JPanel bottom = new JPanel(new BorderLayout(0, 8));
		bottom.add(presetRow, BorderLayout.NORTH);
		bottom.add(resetAll, BorderLayout.SOUTH);

		JPanel top = new JPanel(new BorderLayout(4, 4));
		top.add(subtitle, BorderLayout.NORTH);
		top.add(previewLabel, BorderLayout.CENTER);
		JPanel modeAndHint = new JPanel(new BorderLayout());
		modeAndHint.add(modePanel, BorderLayout.NORTH);
		modeAndHint.add(hintLabel, BorderLayout.SOUTH);
		top.add(modeAndHint, BorderLayout.SOUTH);

		JPanel content = new JPanel(new BorderLayout(8, 8));
		content.setBorder(new EmptyBorder(10, 10, 10, 10));
		content.add(top, BorderLayout.NORTH);
		content.add(fields, BorderLayout.CENTER);
		content.add(bottom, BorderLayout.SOUTH);
		setContentPane(content);

		pack();
		setLocationRelativeTo(null);

		addWindowListener(new WindowAdapter() {
			@Override
			public void windowClosed(WindowEvent e) {
				commitThrottle.stop();
				previewExecutor.shutdownNow();
			}
		});

		commit();
		schedulePreview();
	}

	private void setMode(Mode newMode) {
		mode = newMode;
		updateHint();
	}

	private void updateHint() {
		switch (mode) {
			case ROTATE:
				hintLabel.setText("Drag rotate · Right-drag roll · Wheel zoom");
				break;
			case PAN:
				hintLabel.setText("Drag to pan · Wheel zoom");
				break;
			case SCALE:
				hintLabel.setText("Drag to resize · Wheel zoom");
				break;
		}
	}

	private void attachDragControls() {
		// Screen coordinates, since a drag routinely leaves the small preview label and
		// component-relative ones stop tracking properly once outside its bounds
		previewLabel.addMouseListener(new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent e) {
				dragX = e.getXOnScreen();
				dragY = e.getYOnScreen();
			}
		});
		previewLabel.addMouseMotionListener(new MouseMotionAdapter() {
			@Override
			public void mouseDragged(MouseEvent e) {
				int dx = e.getXOnScreen() - dragX;
				int dy = e.getYOnScreen() - dragY;
				dragX = e.getXOnScreen();
				dragY = e.getYOnScreen();
				if (SwingUtilities.isRightMouseButton(e)) {
					nudge(angleZSpinner, dx * ANGLE_PER_DRAG_PIXEL);
					return;
				}
				switch (mode) {
					case ROTATE:
						nudge(angleYSpinner, dx * ANGLE_PER_DRAG_PIXEL);
						nudge(angleXSpinner, dy * ANGLE_PER_DRAG_PIXEL);
						break;
					case PAN: {
						double panSensitivity = panUnitsPerDragPixel();
						nudge(panXSpinner, dx * panSensitivity);
						nudge(panYSpinner, dy * panSensitivity);
						break;
					}
					case SCALE:
						nudge(resizeXSpinner, dx * RESIZE_PER_DRAG_PIXEL);
						nudge(resizeYSpinner, -dy * RESIZE_PER_DRAG_PIXEL);
						break;
				}
			}
		});
		previewLabel.addMouseWheelListener(e -> nudge(zoomSpinner, e.getWheelRotation() * ZOOM_PER_WHEEL_NOTCH));
	}

	private void nudge(JSpinner spinner, double delta) {
		if (delta == 0)
			return;
		spinner.setValue(spinnerValue(spinner) + (int) Math.round(delta));
	}

	/**
	 * Inverts the rasterizer's perspective projection so a dragged pixel moves the icon by a
	 * pixel. A fixed rate can't work, since the projection divides by the current zoom.
	 */
	private double panUnitsPerDragPixel() {
		return spinnerValue(zoomSpinner) / (double) (PREVIEW_SCALE * ItemIconRasterizer.PROJECTION_SCALE);
	}

	private static JSpinner newSpinner(int value) {
		JSpinner spinner = new JSpinner(new SpinnerNumberModel(value, -SPINNER_BOUND, SPINNER_BOUND, 1));
		spinner.setEditor(new JSpinner.NumberEditor(spinner, "#,##0"));
		return spinner;
	}

	private static int spinnerValue(JSpinner spinner) {
		return ((Number) spinner.getValue()).intValue();
	}

	private JPanel fieldRow(String text, JSpinner spinner, IntSupplier defaultValue) {
		JButton reset = new JButton(RESET_ICON);
		reset.setMargin(new Insets(0, 4, 0, 4));
		reset.setToolTipText("Reset " + text);
		reset.addActionListener(e -> applyImmediately(() -> spinner.setValue(defaultValue.getAsInt())));

		JPanel panel = new JPanel(new BorderLayout(4, 0));
		JLabel label = new JLabel(text);
		label.setPreferredSize(new Dimension(60, label.getPreferredSize().height));
		panel.add(label, BorderLayout.WEST);
		panel.add(spinner, BorderLayout.CENTER);
		panel.add(reset, BorderLayout.EAST);
		return panel;
	}

	private void applyToSpinners(CustomRotation rotation) {
		zoomSpinner.setValue(rotation.zoom2d);
		panXSpinner.setValue(rotation.offsetX);
		panYSpinner.setValue(rotation.offsetY);
		angleXSpinner.setValue(rotation.xan2d);
		angleYSpinner.setValue(rotation.yan2d);
		angleZSpinner.setValue(rotation.zan2d);
		resizeXSpinner.setValue(rotation.resizeX);
		resizeYSpinner.setValue(rotation.resizeY);
		resizeZSpinner.setValue(rotation.resizeZ);
	}

	private CustomRotation currentRotation() {
		return new CustomRotation(spinnerValue(angleXSpinner), spinnerValue(angleYSpinner), spinnerValue(angleZSpinner),
			spinnerValue(zoomSpinner), spinnerValue(panXSpinner), spinnerValue(panYSpinner),
			spinnerValue(resizeXSpinner), spinnerValue(resizeYSpinner), spinnerValue(resizeZSpinner));
	}

	/**
	 * A spinner changed, from typing, a drag or the wheel. The preview re-renders right away;
	 * the commit is throttled separately, being the expensive half.
	 */
	private void onValueChanged() {
		schedulePreview();
		scheduleCommit();
	}

	/** Commits a change immediately, bypassing the throttle - for buttons, which shouldn't lag. */
	private void applyImmediately(Runnable change) {
		change.run();
		commitThrottle.stop();
		commit();
	}

	private void scheduleCommit() {
		// start() on a running Timer is a no-op, not a restart, which is what makes this a
		// throttle rather than a debounce
		if (!commitThrottle.isRunning())
			commitThrottle.start();
	}

	private void commit() {
		CustomRotation rotation = currentRotation();
		// Having no override at all is what being at the defaults means: the icon goes back to
		// being fitted to the game's own, rather than placed from these values
		if (rotation.equals(defaults))
			rotationStorage.remove(itemId);
		else
			rotationStorage.put(itemId, rotation);
		onChanged.accept(itemId);
	}

	private void schedulePreview() {
		CustomRotation rotation = currentRotation();
		boolean atDefaults = rotation.equals(defaults);
		long generation = ++previewGeneration;
		previewExecutor.execute(() -> {
			// Skip stale work rather than letting a burst of changes queue up behind rendering
			if (generation != previewGeneration)
				return;
			ItemIconRasterizer rasterizer = new ItemIconRasterizer(model, rotation.xan2d, rotation.yan2d, rotation.zan2d,
				rotation.resizeX, rotation.resizeY, rotation.resizeZ, supersample);
			// At the defaults the icon itself is fitted to the game's own, so the preview is too,
			// or the two would disagree on what the default even looks like
			boolean fitted = atDefaults && referencePixels != null
				&& rasterizer.fitToReferenceSilhouette(referencePixels, palette);
			if (!fitted)
				rasterizer.placeExplicitly(rotation.zoom2d, rotation.offsetX, rotation.offsetY);
			// Unsharpened: this preview is magnified, not stretched by the interface
			int[] pixels = rasterizer.render(0, false, false, palette);
			SwingUtilities.invokeLater(() -> {
				if (generation != previewGeneration)
					return;
				previewLabel.setIcon(new ImageIcon(scale(toImage(pixels))));
			});
		});
	}

	private static BufferedImage toImage(int[] pixels) {
		BufferedImage image = new BufferedImage(ICON_WIDTH, ICON_HEIGHT, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(0, 0, ICON_WIDTH, ICON_HEIGHT, pixels, 0, ICON_WIDTH);
		return image;
	}

	private static Image scale(BufferedImage image) {
		return image.getScaledInstance(ICON_WIDTH * PREVIEW_SCALE, ICON_HEIGHT * PREVIEW_SCALE, Image.SCALE_FAST);
	}
}

